window.POEM_DB=window.POEM_DB||{};POEM_DB["song_025"]={"n":"邵雍","dyn":"宋","poems":[{"t":"和王安之同赴府尹王宣徽洛社秋会","f":"七言律诗","c":["后房深出会亲宾，乐按新声妙入神。","红烛盛时翻翠袖，画桡停处占青蘋。","早年金殿旧游客，此日凤池将去人。","宅冠名都号蜗隐，邵尧夫敢作西邻。"]},{"t":"延福坊李太博乞园池诗","f":"七言律诗","c":["宣威十九次高牙，奕叶功臣旧将家。","清世辞荣归里第，白头行乐过年华。","杯盈香醑浮春水，曲度新声出靓花。","如此园池如此寿，儿孙满眼庆无涯。"]},{"t":"追和王常侍登郡楼望山","f":"七言律诗","c":["四贤当日此盘桓，千百年人尚厚颜。","天下有名难避世，胸中无物漫居山。","事观今古兴亡后，道在君臣进退间。","若蕴奇才必奇用，不然须负一生闲。"]},{"t":"留题龙门二首 其一","f":"七言律诗","c":["融结成来不记秋，断崖苍壁锁烟愁。","中分洪造夏王力，横截大山伊水流。","八节滩声长在耳，一川风景尽归楼。","行人莫动凭栏兴，无限英雄浪白头。"]},{"t":"二十二日晚步天津次日有诗","f":"七言律诗","c":["溪翁昨晚步天津，步到天津伫立频。","洛水只闻煎去棹，西风唯解促行人。","山川惨淡笼寒雨，楼观参差锁暮云。","此景分明谁会得，欲霜时候雁来宾。"]},{"t":"天津晚步","f":"五言古诗","c":["芝盖久稀疏，暮云空坱北。","千年旧都城，一片闲宫阙。","禁籞尚连延，觚棱犹巀嶭。","桥势横雌霓，堤形偃初月。","瀍涧岸已深，汉唐时既歇。","危亭独坐人，浪把兴亡阅。"]},{"t":"依韵和王安之少卿六老诗仍见率成七首 其五","f":"七言律诗","c":["六客同游一醉乡，又非流俗所言狂。","追游共喜清平久，唱和争寻警策忙。","荐酒月陂林果熟，发茶金谷井泉香。","千年松下麾谈麈，襟袖无风亦自凉。"]},{"t":"和任比部忆梅","f":"七言绝句","c":["痛忆梅开易得残，既残憔悴不堪看。","年年长被清香误，争似闲栽竹数竿。"]},{"t":"代书寄祖龙图","f":"五言律诗","c":["三十年交旧，相逢各白头。","海壖曾共饮，洛社又同游。","脱屣风波地，开怀松桂秋。","两眉从此后，应不著闲愁。"]},{"t":"七日溯洛夜宿延秋庄上","f":"七言绝句","c":["八月延秋禾熟天，农家富贵在丰年。","一箪鸡黍一瓢酒，谁羡王公食万钱。"]},{"t":"七国","f":"七言绝句","c":["七国纵横事可明，苏张得路信非平。","当初天下如何尔，市井之人为正卿。"]},{"t":"九日登寿安县锦屏山下宿邑中 其一","f":"七言绝句","c":["烟岚一簇特崔鬼，到此令人心自灰。","上有神仙不知姓，洞门闲倚白云开。"]},{"t":"九日登寿安县锦屏山下宿邑中 其二","f":"七言绝句","c":["并辔西游叠石溪，断崖环合与云齐。","飞泉亦有留人意，肯负他年尚此栖。"]},{"t":"二色桃","f":"七言绝句","c":["施朱施粉色俱好，倾国倾城艳不同。","疑是蕊宫双姊妹，一时俱肯嫁春风。"]},{"t":"人事吟","f":"五言绝句","c":["索鍊无如事，难知莫若人。","人情随手别，事体到头均。"]},{"t":"人情吟","f":"五言绝句","c":["古事参今事，今人乃古人。","只应情未浃，情浃自相亲。"]},{"t":"十一日福昌县会雨","f":"五言绝句","c":["云势移峰缓，泉声出竹迟。","此时无限意，唯有翠禽知。"]},{"t":"十七日锦屏山下谢城中张孙二君惠茶","f":"七言绝句","c":["山似捼蓝波似染，游心一向难拘检。","仍携二友所分茶，每到烟岚深处点。"]},{"t":"十九日归洛城路游龙门 其一","f":"七言绝句","c":["伊川往复过龙山，每过龙山意且闲。","莫道移人不由境，可堪深著利名间。"]},{"t":"十九日归洛城路游龙门 其二","f":"七言绝句","c":["无烦物象弄精神，世态何常不喜新。","唯有前墀好风月，清光依旧属闲人。"]},{"t":"十八日逾牵羊坂南达伊川坟上","f":"七言绝句","c":["三尺荒坟百尺山，生身慈爱在其间。","此情至死不能尽，日暮徘徊又且还。"]},{"t":"十三日游上寺及黄涧二首 其一","f":"七言绝句","c":["能休尘境为真境，未了僧家是俗家。","不向此中寻洞府，更于何处觅藏花。"]},{"t":"十三日游上寺及黄涧二首 其二","f":"七言绝句","c":["堪嗟五伯争周烬，可笑三分拾汉馀。","何似不才闲处坐，平时云水绕衣裾。"]},{"t":"十五日别福昌因有所感","f":"七言绝句","c":["连昌宫废昌河在，事去时移语浪传。","下有荒祠难问处，古槐枝秃竹参天。"]},{"t":"十日西过永济桥","f":"七言绝句","c":["十日西行过永济，时时细雨湿衫衣。","多情会得山神意，犹恐行人欠翠微。"]},{"t":"代书寄剑州普安令周士彦屯田又一绝","f":"七言绝句","c":["正当老辈过从日，况值高秋摇落天。","一把黄花一樽酒，故人西去又经年。"]},{"t":"伤二舍弟无疾而化又一绝","f":"五言绝句","c":["手足恩情重，埙篪欢乐长。","要知能忘处，坟草两荒凉。"]},{"t":"又借出诗","f":"五言绝句","c":["安乐窝中乐，娲皇笙万攒。","自从闲借出，客到遂无欢。"]},{"t":"三王","f":"七言绝句","c":["三王之世正如秋，权重权轻事有由。","深谷为陵岸为谷，陵迁谷变不知休。"]},{"t":"上巳观花思友人","f":"七言绝句","c":["上巳观花花意秾，今年正与昔年同。","当时同赏知何处，把酒犹能对远风。"]},{"t":"大笔吟 其一","f":"五言绝句","c":["诗成大字书，意快有谁如。","巨浪银山立，风樯百尺馀。"]},{"t":"小车行","f":"七言绝句","c":["喜醉岂无千日酒，惜春还有四时花。","小车行处人欢喜，满洛城中都似家。"]},{"t":"小车初出吟","f":"七言绝句","c":["物外洞天三十六，都疑布在洛阳中。","小车春暖秋凉日，一日止能移一宫。"]},{"t":"小车吟","f":"五言绝句","c":["春暖未苦热，秋凉未甚寒。","小车随意出，所到即成欢。"]},{"t":"小车吟","f":"七言绝句","c":["春暖秋凉兼景好，年丰身健更时和。","如茵草上轻轻碾，似锦花间慢慢拖。"]},{"t":"小园逢春","f":"七言绝句","c":["小隐园中百本花，各随红紫发新芽。","东君见借阳和力，不减公侯富贵家。"]},{"t":"山中寄登封令","f":"七言绝句","c":["初离县日谋经宿，既到山中未忍回。","公宇若无民事决，愿携茶器上山来。"]},{"t":"不老吟","f":"五言绝句","c":["人无不老理，日有再中时。","不老必无也，再中应有之。"]},{"t":"五帝","f":"七言绝句","c":["五帝之时似日中，声明文物正融融。","古今世盛无如此，过此其来便不同。"]},{"t":"五相","f":"五言绝句","c":["北巷通南陌，门连五相家。","水分池对岸，墙隔树交花。"]},{"t":"天人吟","f":"七言绝句","c":["羲轩尧舜虽难复，汤武桓文尚可循。","事既不同时又异，也由天道也由人。"]},{"t":"天宫小阁纳凉 其一","f":"七言绝句","c":["小阁凭虚看洛城，满川云物拱神京。","风从万岁山头至，多少烟岚并此清。"]},{"t":"天宫小阁纳凉 其二","f":"七言绝句","c":["小阁于吾有大功，清凉冠绝洛城中。","自惭虚薄诚多幸，襟袖长涵万里风。"]},{"t":"天津看雪代简谢蒋秀才还诗卷","f":"五言绝句","c":["清洛接天去，寒云贴地飞。","人于桥上立，诗向雪中归。"]},{"t":"天津闻乐吟","f":"七言绝句","c":["名园相倚洛阳春，巷陌无尘罗绮新。","何处青楼隔桃李，乐声时复到天津。"]},{"t":"天津感事二十六首 其二十六","f":"七言绝句","c":["了生始可言常事，知性方能议大猷。","只此长川无昼夜，为谁驱逼向东流。"]},{"t":"天津感事二十六首 其二十五","f":"七言绝句","c":["郏鄏城中同德友，凤凰楼下会中秋。","芳樽倒尽人归去，月色波光战未休。"]},{"t":"天津感事二十六首 其二十四","f":"七言绝句","c":["云无一缕干明月，桥有千寻卧渌波。","料得人间无此景，中秋对月兴如何。"]},{"t":"天津感事二十六首 其二十三","f":"七言绝句","c":["前朝无限贵公卿，后世徒能记姓名。","唯此天津桥下水，古今都作一般声。"]},{"t":"天津感事二十六首 其二十二","f":"七言绝句","c":["隋唐而下贵公卿，近世风波走利名。","借问天津桥下水，当时湍急作何声。"]},{"t":"天津感事二十六首 其二十一","f":"七言绝句","c":["着身静处观人事，放意闲中鍊物情。","去尽风波存止水，世间何事不能平。"]},{"t":"天津感事二十六首 其二十","f":"七言绝句","c":["绕堤杨柳轻风里，隔水楼台细雨中。","酒放半醺重九后，此时情味更无穷。"]},{"t":"天津感事二十六首 其十九","f":"七言绝句","c":["三千里外名荒服，一百年来号太平。","争似洛川无事客，何须列土始为荣。"]},{"t":"天津感事二十六首 其十八","f":"七言绝句","c":["地势东南一槩倾，水流何日得安平。","天津更在急流处，无限高深并此声。"]},{"t":"天津感事二十六首 其十七","f":"七言绝句","c":["名利从来本任才，行人不用苦相猜。","壶中日月长多少，闲步天津看往来。"]},{"t":"天津感事二十六首 其十六","f":"七言绝句","c":["溪边闲坐眼慵开，波射长堤势欲摧。","多少水禽文彩好，几番飞去又飞来。"]},{"t":"天津感事二十六首 其十五","f":"七言绝句","c":["水流任急境常静，花落虽频意自闲。","不似世人忙里老，生平未始得开颜。"]},{"t":"天津感事二十六首 其十四","f":"七言绝句","c":["堤边草色长芊芊，陌上行人自往还。","渌水欲净不得净，春风未放柳条闲。"]},{"t":"天津感事二十六首 其十三","f":"七言绝句","c":["去年桥上凭栏人，今岁桥边骑马身。","桥上桥边不知数，于今但记十三春。"]},{"t":"天津感事二十六首 其十二","f":"七言绝句","c":["渌水悠悠际碧天，平芜更与远山连。","白头老叟心无事，闲凭栏干看洛川。"]},{"t":"天津感事二十六首 其十一","f":"七言绝句","c":["烟树尽归秋色里，人家常在水声中。","数行旅雁斜飞去，一簇楼台峭倚空。"]},{"t":"天津感事二十六首 其十","f":"七言绝句","c":["轮蹄交错未尝停，去若相追来若争。","料得中心无别事，苟非干利即干名。"]},{"t":"天津感事二十六首 其九","f":"七言绝句","c":["凤凰楼观冷横秋，桥下长波入海流。","千百年来旧朝市，几番人向此经由。"]},{"t":"天津感事二十六首 其八","f":"七言绝句","c":["自古别都多隙地，参天乔木乱昏鸦。","荒垣坏堵人耕处，半是前朝卿相家。"]},{"t":"天津感事二十六首 其七","f":"七言绝句","c":["人言垂钓辩浮沉，辩著浮沉用意深。","吾耻不为知害性，等闲轻动望鱼心。"]},{"t":"天津感事二十六首 其六","f":"七言绝句","c":["忙忙负乘两何殊，往复由来出此途。","争似不才闲处坐，平时云水绕衣裾。"]},{"t":"天津感事二十六首 其五","f":"七言绝句","c":["阳乌西去水东流，今古推移几度秋。","四面远山长敛黛，不知终日为谁愁。"]},{"t":"天津感事二十六首 其四","f":"七言绝句","c":["谁引长河贯洛城，銮舆东去此为轻。","洪涛不服天津束，日夜奔腾作怒声。"]},{"t":"天津感事二十六首 其三","f":"七言绝句","c":["凤楼深处锁云烟，一锁云烟又百年。","痛惜汾阴西祀后，翠华辜负上阳天。"]},{"t":"天津感事二十六首 其二","f":"七言绝句","c":["宠辱事多今不见，兴亡时去止堪哀。","请观今日长安道，抵暮行人犹往来。"]},{"t":"天津感事二十六首 其一","f":"七言绝句","c":["云轻日淡天津暮，风急林疏洛水秋。","独步独吟人莫会，时时鸥鹭下汀洲。"]},{"t":"天意吟","f":"七言绝句","c":["人能言语自能窥，天意无言人莫欺。","莫道无言便无事，殆非流俗所能知。"]},{"t":"太平吟","f":"五言绝句","c":["天下太平日，人生安乐时。","更逢花烂漫，争忍不开眉。"]},{"t":"太平吟","f":"七言绝句","c":["太平时世园亭内，丰稔岁年村落间。","情味一般难状处，风烟草木尽闲闲。"]},{"t":"忆梦吟","f":"五言绝句","c":["心足而家贫，体疏而情亲。","开襟知骨瘦，发语见天真。"]},{"t":"日中吟","f":"五言绝句","c":["日中为噬嗑，交易是寻常。","彼各不相识，何复更思量。"]},{"t":"月陂闲步","f":"七言绝句","c":["因随芳草行来远，为爱清波归去迟。","独步独吟仍独坐，初凉天气未寒时。"]},{"t":"月新吟","f":"五言绝句","c":["月新与月残，形状两相似。","奈何人之情，初见自欢喜。"]},{"t":"见物吟","f":"五言绝句","c":["见物即讴吟，何尝曾用意。","闲将筐笥诗，静看人间事。"]},{"t":"东轩黄红二梅正开坐上书呈友人","f":"七言绝句","c":["一年一度见双梅，能见双梅几度开。","人寿百年今六十，休论闲事且衔杯。"]},{"t":"代书寄吕库部","f":"七言绝句","c":["周王八骏走天涯，争似君家四宝奇。","郑洛风烟虽咫尺，恨无由往一观之。"]},{"t":"代简答张淳秘校","f":"七言绝句","c":["老年前事怕追思，更见曾悲先德诗。","却有断章聊自慰，如今冢嗣弱于谁。"]},{"t":"代简谢尹处初先生","f":"七言绝句","c":["乐国久容人避乖，非窝何以状清怀。","则予岂敢窥高躅，天险能升不用阶。"]},{"t":"代简谢王茂直惠酒及川笺","f":"七言绝句","c":["白羊玉屑诚佳物，臂痛头风正苦时。","酒放半醺诗思动，窝中何用更呼医。"]},{"t":"代简谢朱殿直赠长韵诗","f":"七言绝句","c":["慇勤见赠用长篇，里闬过从积有年。","岁事报成还报始，春华相次又暄妍。"]},{"t":"可必吟","f":"七言绝句","c":["可必人间唯善事，不由天地只由衷。","莫嫌效远因而止，更勉其来更有功。"]},{"t":"可惜吟","f":"七言绝句","c":["可惜熙熙一片春，不多时节觅无因。","眼前园苑知何限，只见莺啼不见人。"]},{"t":"四小吟简陈季常","f":"五言绝句","c":["八月小春天，小花开且殷。","晚来经小雨，遂使小车闲。"]},{"t":"对花","f":"五言绝句","c":["新花色鲜艳，故花色憔悴。","明朝花更开，新花何有异。"]},{"t":"对花吟","f":"七言绝句","c":["美酒岂无留客饮，好花犹解向人开。","多情不忍阻花意，未醉何须辞满杯。"]},{"t":"归城中再用前韵","f":"七言绝句","c":["初秋微雨造轻寒，倚遍东岑阁上栏。","不谓是时烟霭里，松斋人作画图看。"]},{"t":"归城中再用前韵","f":"七言绝句","c":["乘兴龙山访尽幽，恰如人在画图游。","恨无美酒酬佳景，正欲留时不得留。"]},{"t":"未有吟 其二","f":"五言绝句","c":["未有一分让，先有十分争。","所丧者实事，所得者虚名。"]},{"t":"白头吟","f":"五言绝句","c":["五福虽难备，三殇却不逢。","太平无事日，得作白头翁。"]},{"t":"伤心行","f":"七言绝句","c":["不知何铁打成针，一打成针只刺心。","料得人心不过寸，刺时须刺十分深。"]},{"t":"先天吟","f":"七言绝句","c":["若问先天一字无，后天方要着工夫。","拔山盖世称才力，到此分毫强得乎。"]},{"t":"光阴吟","f":"七言绝句","c":["三百六旬有六日，光阴过眼如奔轮。","周而复始未尝息，安得四时长似春。"]},{"t":"再用晴窗气暖墨花春谢王胜之谏议惠金雀砚","f":"七言绝句","c":["砚名金雀世难伦，用报惭无天下珍。","国士有诗偏雅处，晴窗气暖墨花春。"]},{"t":"再答王宣徽 其二","f":"五言绝句","c":["大达诚无碍，人人自有家。","假花犹入念，何者谓真花。"]},{"t":"再答王宣徽 其一","f":"五言绝句","c":["自有吾儒乐，人多不肯循。","以禅为乐事，又起一重尘。"]},{"t":"同诸友城南张园赏梅十首 其十","f":"七言绝句","c":["人间好物尤宜惜，天下奇才非易得。","他日相逢他处时，始知此会重难觅。"]},{"t":"同诸友城南张园赏梅十首 其九","f":"七言绝句","c":["五岭虽多何足观，三川纵少须重去。","台边况有数千株，仍在名园最深处。"]},{"t":"同诸友城南张园赏梅十首 其八","f":"七言绝句","c":["梅花四种或黄红，颜色不同香颇同。","更远也须重一到，看看随水又随风。"]},{"t":"同诸友城南张园赏梅十首 其七","f":"七言绝句","c":["春早梅花正烂开，生平不饮亦衔杯。","城南尽日高台上，恰似江南去一回。"]},{"t":"同诸友城南张园赏梅十首 其六","f":"七言绝句","c":["酒中渍后香尤烈，笛里吹来韵更清。","此韵此香来处好，此时消得一凝情。"]},{"t":"同诸友城南张园赏梅十首 其五","f":"七言绝句","c":["梅台赏罢意何如，归插梅花登小车。","陌上行人应见笑，风情不薄是尧夫。"]},{"t":"同诸友城南张园赏梅十首 其四","f":"七言绝句","c":["红日坠时情更切，玉山颓处兴还深。","攀条时拣繁枝折，不插满头辜此心。"]},{"t":"同诸友城南张园赏梅十首 其三","f":"七言绝句","c":["清香冷艳偏多处，猛雨狂风未有前。","赏意正浓红日坠，如何既去遂经年。"]},{"t":"同诸友城南张园赏梅十首 其二","f":"七言绝句","c":["折来嗅了依前嗅，重惜清香难久留。","多谢主人情意切，未残仍许客重游。"]},{"t":"同诸友城南张园赏梅十首 其一","f":"七言绝句","c":["东风一夜坼梅枝，舞蝶游蜂都不知。","插了满头仍渍酒，任他人道拙于时。"]},{"t":"好事吟","f":"七言绝句","c":["好事固难将力取，贤人须是著心求。","浮生日月无多子，时过千休复万休。"]},{"t":"好勇吟","f":"五言绝句","c":["好勇能过我，当仁岂让师。","勇须仁以济，仁必勇为资。"]},{"t":"孙庞二将","f":"七言绝句","c":["孙膑伏兵称有法，庞涓钻火一何愚。","兵家诡诈尽如此，利害今人自不殊。"]},{"t":"安分吟","f":"五言绝句","c":["安分身无辱，知几心自闲。","虽居人世上，却是出人间。"]},{"t":"安乐窝前蒲柳吟","f":"七言绝句","c":["安乐窝前小江曲，新蒲细柳年年绿。","眼前随分好光阴，谁道人生多不足。"]},{"t":"岁寒吟","f":"五言绝句","c":["松柏入冬看，方能见岁寒。","声须风里听，色更雪中观。"]},{"t":"戏谢富相公惠班笋三首 其三","f":"七言绝句","c":["应物功夫出世间，岂容人可强跻攀。","我侬自是不知量，培塿须求比泰山。"]},{"t":"戏谢富相公惠班笋三首 其二","f":"七言绝句","c":["承将大笋来相诧，小圃其如都不生。","虽向性情曾著力，奈何今日未能平。"]},{"t":"戏谢富相公惠班笋三首 其一","f":"七言绝句","c":["名园不放过鸦飞，相国如今遂请时。","鼎食从来称富贵，更和花笋一兼之。"]},{"t":"扫地吟","f":"七言绝句","c":["管晏治时犹有体，苏张用处更无名。","三皇五帝从何出，扫地中原俟太平。"]},{"t":"有病吟","f":"五言绝句","c":["一身如一国，有病当求医。","病愈药便止，节宣良得宜。"]},{"t":"欢笑","f":"七言绝句","c":["划平荆棘盖楼台，楼上笙簧鼎沸开。","欢笑未绝兵火起，从前荆棘却生来。"]},{"t":"欢喜吟","f":"五言绝句","c":["扬善不扬恶，记恩不记雠。","人人自欢喜，何患少交游。"]},{"t":"污亭","f":"七言绝句","c":["许由为计未为深，洗耳如何不动心。","到此洒然如世外，何尝更有事来侵。"]},{"t":"百年吟","f":"五言绝句","c":["百年嗟荏苒，千里痛萧条。","忍逐东流水，无期任所飘。"]},{"t":"自庆吟","f":"五言绝句","c":["俗阜知君德，时和见帝功。","况吾生长老，俱在太平中。"]},{"t":"自况三首 其一","f":"七言绝句","c":["名利场中难着脚，林泉路上早回头。","不然半百残躯体，正被风波汨未休。"]},{"t":"自述","f":"七言绝句","c":["春暖秋凉人半醉，安车麈尾闲从事。","虽无大德及生灵，且与太平装景致。"]},{"t":"自谢用此乐直从天外来","f":"七言绝句","c":["得自苦时终入苦，来从哀处卒归哀。","既非哀苦中间得，此乐直从天外来。"]},{"t":"芍药四首 其一","f":"七言绝句","c":["花不能言意已知，今君慵饮更无疑。","但知白酒留佳客，直待琼丹覆玉彝。"]},{"t":"芍药四首 其二","f":"七言绝句","c":["一声啼鴂画楼东，魏紫姚黄扫地空。","多谢化工怜寂寞，尚留芍药殿春风。"]},{"t":"芍药四首 其三","f":"七言绝句","c":["含露仙姿近玉堂，翻阶美态醉红妆。","对花未免须酣舞，到底昌黎是楚狂。"]},{"t":"芍药四首 其四","f":"七言绝句","c":["阿姨天上舞霓裳，姊妹庭前剪雪霜。","要与牡丹为近侍，铅华不待学梅妆。"]},{"t":"行止吟","f":"五言绝句","c":["时止则须止，时行则可行。","时行与时止，人力莫经营。"]},{"t":"观物吟二首 其二","f":"五言绝句","c":["百谷仰膏雨，极枯变极荣。","安得此甘泽，聊且振群生。"]},{"t":"观物吟二首 其一","f":"五言绝句","c":["柳性至柔软，一年长丈馀。","虽然易得荣，奈何易得枯。"]},{"t":"观棋绝句 其一","f":"五言绝句","c":["未去交争意，难忘黑白心。","一条无敌路，彻了没人寻。"]},{"t":"观棋绝句 其二","f":"五言绝句","c":["未去交争意，难忘黑白情。","一条平稳路，痛惜没人行。"]},{"t":"访南园张氏昆仲因而留宿","f":"七言绝句","c":["中秋天气随宜好，来访南园会隐家。","贪饮不知归去晚，水精宫里宿烟霞。"]},{"t":"过宜阳城二首 其二","f":"七言绝句","c":["当日宜阳号别都，奈何韩国特区区。","子房不得宣遗恨，博浪沙中中副车。"]},{"t":"过宜阳城二首 其一","f":"七言绝句","c":["六国区区共事秦，疲于奔命尚难亲。","如何杀尽半天下，岂是关东没一人。"]},{"t":"过温寄巩县宰吴秘丞","f":"七言绝句","c":["风软玉溪腾醉骑，花繁石窟漾歌舟。","相望咫尺仙凡隔，不得同陪三月游。"]},{"t":"问春 其三","f":"七言绝句","c":["春来愁去只因花，春去愁来翻殢酒。","长恨愁多酒力微，为春成病花知否。"]},{"t":"齐郑吟","f":"七言绝句","c":["子产何尝辞郑小，晏婴殊不愿齐衰。","二贤生若得其地，才业当为王者师。"]},{"t":"利名吟","f":"七言绝句","c":["利名都不到胸中，由此胸中气自冲。","既爱且憎皆是病，灵台何日得从容。"]},{"t":"别两绝 其二","f":"五言绝句","c":["赏花高阁上，负约罪难回。","若许将诗赎，何时不可陪。"]},{"t":"别两绝 其一","f":"七言绝句","c":["楼外花深碍小车，难忘有德见思多。","欲凭桃李为之谢，桃李无言争奈何。"]},{"t":"别寄一首","f":"七言绝句","c":["许大秦皇定九州，九州才定却归刘。","它人莫谩誇精彩，徒自区区撰白头。"]},{"t":"别谢彦国相公三首 其二","f":"七言绝句","c":["仲尼天纵自诚明，造化功夫发得成。","见比当初归鲁事，尧夫才业若为情。"]},{"t":"吴越吟二首 其二","f":"七言绝句","c":["夫差丁未曾囚越，勾践戊辰还灭吴。","二十二年时返复，一如当日却乘虚。"]},{"t":"吴越吟二首 其一","f":"七言绝句","c":["乙未阖庐凌楚岁，戊辰勾践破吴时。","正如当日乘虚事，三十四年人不知。"]},{"t":"呈富相风筝","f":"七言绝句","c":["秋风一击入云端，合国人皆仰面观。","好向丹霄休索线，等闲势断却收难。"]},{"t":"杏香花","f":"五言绝句","c":["客说河州事，经营杳未涯。","讶予独无语，贪嗅杏香花。"]},{"t":"步月吟","f":"五言绝句","c":["林罅天尤碧，风馀月更明。","人间无事日，得向此中行。"]},{"t":"牡丹吟","f":"七言绝句","c":["一般颜色一般香，香是天香色异常。","真宰功夫精妙处，非容人意可思量。"]},{"t":"牡丹吟","f":"七言绝句","c":["牡丹花品冠群芳，况是其间更有王。","四色变而成百色，百般颜色百般香。"]},{"t":"言行吟","f":"五言绝句","c":["能言未是难，行得始为艰。","须是真男子，方能无厚颜。"]},{"t":"言语吟","f":"五言绝句","c":["一语便喜处，千言益怒时。","既因言语合，却为语言离。"]},{"t":"言默吟","f":"七言绝句","c":["当默用言言是垢，当言任默默为尘。","当言当默都无任，尘垢何由得到身。"]},{"t":"邹田二忌","f":"七言绝句","c":["邹田二忌不相能，买卜之言恶足明。","利害伤真至于此，姓田人去恨难平。"]},{"t":"里闬吟 其一","f":"五言绝句","c":["里闬闲过从，太平之盛事。","吾乡多吉人，况与他乡异。"]},{"t":"闲居述事 其六","f":"七言绝句","c":["花木四时分景致，经书千卷好生涯。","有人若问闲居处，道德坊中第一家。"]},{"t":"闲居述事 其四","f":"七言绝句","c":["堂上慈亲八十馀，阶前儿女戏相呼。","旨甘取足随丰俭，此乐人间更有无。"]},{"t":"闲居述事 其一","f":"七言绝句","c":["一点天真都不耗，千钟人禄是难来。","太平自庆无他事，有酒时时三五杯。"]},{"t":"闲居述事 其二","f":"七言绝句","c":["竹雨侵人气自凉，南窗睡起望潇湘。","茅檐滴沥无休歇，却忆当初宿夜航。"]},{"t":"闲居述事 其五","f":"七言绝句","c":["清欢少有虚三日，剧饮未尝过五分。","相见心中无别事，不评兴废即论文。"]},{"t":"事急吟","f":"五言绝句","c":["旱极望雨意，病危思药心。","人人当此际，不待劝而深。"]},{"t":"事体吟","f":"五言绝句","c":["语言须中节，义理贵从宜。","可革仍三就，当行必再思。"]},{"t":"依韵和任司封见寄吟 其三","f":"七言绝句","c":["辞麾来此住云霄，闻健登临肯惮劳。","紫陌事多都不见，家山围绕是嵩高。"]},{"t":"依韵和任司封见寄吟 其一","f":"七言绝句","c":["王侯贵盛不胜言，图画中山得一观。","不似夫君行坐看，贪嵩又更爱天坛。"]},{"t":"依韵和任司封见寄吟 其二","f":"七言绝句","c":["高楼百尺破危空，天淡云闲看帝功。","更上一层情未快，思君不见见乔嵩。"]},{"t":"依韵和君实端明洛滨独步 其一","f":"七言绝句","c":["冠盖纷纷塞九衢，声名相轧在前呼。","独君都不将为事，始信人间有丈夫。"]},{"t":"依韵和君实端明洛滨独步 其二","f":"七言绝句","c":["风背河声近亦微，斜阳淡泊隔云衣。","一双白鹭来烟外，将下沙头又却飞。"]},{"t":"依韵和君实端明惠酒","f":"七言绝句","c":["春风吹雪乱飘飖，林下如何更寂寥。","霜宪威棱正难犯，小人当贶是难消。"]},{"t":"依韵和宋都官惠棕拂子","f":"七言绝句","c":["洛邑从来号别都，能容无状久安居。","众蚊多少成雷处，一拂何由议扫除。"]},{"t":"依韵和张静之少卿惠文房三物","f":"七言绝句","c":["文房三物品皆精，报谢愁无秀句成。","欲状升平在歌颂，奈何才不逮升平。"]},{"t":"依韵和浙宪任度支","f":"七言绝句","c":["官路寻知已得真，可堪轻负洛城春。","江湖相望三千里，休使乡朋想望频。"]},{"t":"依韵谢任司封寄逍遥枕吟","f":"七言绝句","c":["夫君惠我逍遥枕，恐我逍遥迹未超。","形体逍遥终未至，更和魂梦与逍遥。"]},{"t":"凭高吟","f":"七言绝句","c":["谁将酷烈千般毒，变作恩光一派深。","惆怅先民不复见，更凭高处尽沈吟。"]},{"t":"和司马君实崇德久待不至 其一","f":"七言绝句","c":["君家梁上年时燕，过社今年尚未回。","请罚误君凝伫久，万花深处小车来。"]},{"t":"和司马君实崇德久待不至 其二","f":"七言绝句","c":["天启夫君八斗才，野人中路必须回。","神仙一句难忘处，花外小车犹未来。"]},{"t":"和人留题张相公庵","f":"七言绝句","c":["做了三公更引年，人间福德合居先。","结茅未尽忘君处，正在嵩高万岁前。"]},{"t":"和大尹李君锡龙图留别诗","f":"七言绝句","c":["多情大尹辞春去，正是群芳烂漫时。","自古英豪重恩意，群芳慎勿便离披。"]},{"t":"和凤翔横渠张子厚学士亡后篇","f":"七言绝句","c":["秦甸山河半域中，精英孕育古今同。","古来贤杰知多少，何代无人振素风。"]},{"t":"和王平甫教授赏花处惠茶韵","f":"七言绝句","c":["太学先生善识花，得花精处却因茶。","万红香里烹馀后，分送天津第一家。"]},{"t":"和王安之少卿同游龙门 其二","f":"七言绝句","c":["数朝从款看伊流，夜卜香山宿石楼。","会有凉风开远意，更和烟雨弄高秋。"]},{"t":"和王安之少卿同游龙门 其一","f":"七言绝句","c":["生平有癖好寻幽，一岁龙山四五游。","或往或还都不计，盖无荣利可稽留。"]},{"t":"和成都俞公达运使见寄","f":"七言绝句","c":["前年车从过天津，花底当时把酒频。","此日锦城花烂漫，何尝更忆洛城春。"]},{"t":"和君实端明花庵二首 其二","f":"七言绝句","c":["庵后庵前尽植花，花开番次四时好。","主人事简常燕休，不信岁华能撰老。"]},{"t":"和君实端明花庵二首 其一","f":"七言绝句","c":["不用丹楹刻桷为，重重自有翠阴垂。","后人继取天真意，种莳增华非所宜。"]},{"t":"和君实端明洛阳看花 其四","f":"七言绝句","c":["南园一色栽桃李，春到且图花早开。","多谢主人情意厚，天津客不等闲来。"]},{"t":"和君实端明洛阳看花 其二","f":"七言绝句","c":["洛阳花木誇天下，吾辈游胜庶士游。","重念东君分付意，忍于佳处不迟留。"]},{"t":"和君实端明送酒","f":"七言绝句","c":["大凡人意易为骄，双榼何如水一瓢。","亦恐孟光心渐侈，自兹微厌紫芝苗。"]},{"t":"和君实端明副酒之什","f":"七言绝句","c":["洛阳花木满城开，更送东都双榼来。","遂使闲人转狂乱，奈何红日又西颓。"]},{"t":"和君实端明登石阁","f":"五言绝句","c":["平地虽然远，那知物物新。","危楼一百尺，别有万般春。"]},{"t":"和宋都官乞梅","f":"七言绝句","c":["小园虽有四般梅，不似江南迎腊开。","长恨东君少风韵，先时未肯放春来。"]},{"t":"和张少卿丈再到河阳","f":"七言绝句","c":["当年曾任青春客，今日重来白雪翁。","今日当年已一世，几多兴替在其中。"]},{"t":"和李审言龙图行次龙门见寄","f":"七言绝句","c":["万里秋光入坐明，交情预喜笑相迎。","菊花未服重阳过，如待君来泛巨觥。"]},{"t":"和商洛章子厚长官早梅 其二","f":"七言绝句","c":["梅覆春溪水绕山，梅花烂漫水潺湲。","南秦地暖开仍早，比至春初已数番。"]},{"t":"和商洛章子厚长官早梅 其一","f":"七言绝句","c":["只应王母专轻巧，剪碎天边乱白云。","无限清香与清艳，樽前饫享尽输君。"]},{"t":"和商洛章子厚长官早梅 其四","f":"七言绝句","c":["霜扶清格高高起，风驾寒香远远留。","太守多情客多感，金樽倒尽是良筹。"]},{"t":"和商洛章子厚长官早梅 其三","f":"七言绝句","c":["群芳万品递相催，若说高标独有梅。","会得东君无别意，为怜清淡使先开。"]},{"t":"咏世","f":"七言绝句","c":["福艺俱全不可逃，无能无福谩徒劳。","福微艺广终须贵，靠福无能久不高。"]},{"t":"垂柳","f":"七言绝句","c":["门前垂柳正依依，更被东风来往吹。","忘了自家今已老，却疑身是少年时。"]},{"t":"始皇吟","f":"七言绝句","c":["并吞天下九千日，一统寰中十五年。","坑血未乾高祖至，骊山丘垄已萧然。"]},{"t":"府尹王宣徽席上作 其二","f":"七言绝句","c":["纷纷又过一年春，牢落情怀酒漫醇。","满眼暄妍都去尽，樽前唯忆旧交亲。"]},{"t":"府尹王宣徽席上作 其一","f":"七言绝句","c":["留都三判主人翁，大第名园冠洛中。","又喜一年春入手，万花香照酒卮红。"]},{"t":"忠信吟","f":"七言绝句","c":["忠信于人最有情，平居非是鬼神轻。","何须只在江湖上，患难切身然后行。"]},{"t":"杯盘吟","f":"七言绝句","c":["林下杯盘大寂寥，寂寥长愿似今朝。","君看击鼓撞钟者，势去宾朋不易招。"]},{"t":"治平丁未仲秋，游伊洛二川。六日晚，出洛城西门，宿奉亲僧舍，听张道人弹琴","f":"七言绝句","c":["向晚驱车出上阳，初程便宿水云乡。","更闻数弄神仙曲，始信壶中日月长。"]},{"t":"知人吟","f":"七言绝句","c":["事到急时观态度，人于危处露肝脾。","深心厚貌平时可，慎勿便言容易知。"]},{"t":"金玉吟","f":"五言绝句","c":["圣在人中出，心从行上修。","金于沙里得，玉向石中求。"]},{"t":"雨犯吟","f":"七言绝句","c":["这般事业人难继，此个功夫世莫传。","窥牖知天乃常事，不窥牖见是知天。"]},{"t":"雨后天津独步","f":"七言绝句","c":["洛阳宫殿锁晴烟，唐汉以来书可传。","多少升沉都不见，空馀四面旧山川。"]},{"t":"两岁锦屏之游不克见郑令因以寄之","f":"七言绝句","c":["岁岁群芳正烂开，锦屏山下赏春来。","两年不得陪山躅，洞里仙人出未回。"]},{"t":"举世吟","f":"五言绝句","c":["举世自纷纷，谁为无事人。","吾生独何幸，卧看洛阳春。"]},{"t":"南园赏花 其一","f":"七言绝句","c":["三月初三花正开，闲同亲旧上春台。","寻常不醉此时醉，更醉犹能举大杯。"]},{"t":"南园赏花 其二","f":"七言绝句","c":["花前把酒花前醉，醉把花枝仍自歌。","花见白头人莫笑，白头人见好花多。"]},{"t":"思友吟","f":"五言绝句","c":["欲见心无已，久违情奈何。","云烟虽咫尺，不得屡相过。"]},{"t":"思圣吟","f":"五言绝句","c":["不逢圣人时，不见圣人面。","圣人言可闻，圣人心可见。"]},{"t":"思故人","f":"七言绝句","c":["芳酒一樽虽甚满，故人千里奈思何。","柳拖池阁条偏细，花近檐楹香更多。"]},{"t":"思患吟","f":"五言绝句","c":["仆奴凌主人，夷狄犯中国。","自古知不平，无由能绝得。"]},{"t":"思患吟","f":"五言绝句","c":["缘饰近虚襟，虚襟后患深。","疗饥当用食，救旱必须霖。"]},{"t":"思程氏父子兄弟因以寄之 其一","f":"七言绝句","c":["年年时节近中秋，佳水佳山烂漫游。","此际归期为君促，伊川不得久迟留。"]},{"t":"春日登石阁","f":"七言绝句","c":["满洛城中将相家，广栽桃李作生涯。","年年二月凭高处，不见人家只见花。"]},{"t":"春水吟","f":"五言绝句","c":["春水渌成波，成波无奈何。","难将染他物，止可染轻罗。"]},{"t":"春色","f":"七言绝句","c":["去岁春归留不住，今年春色来何处。","洛阳处处是桃源，小车渐转东街去。"]},{"t":"春雨吟","f":"五言绝句","c":["春雨细如丝，如丝霢霂时。","如何一霶霈，万物尽熙熙。"]},{"t":"春暮吟","f":"七言绝句","c":["有意杨花空学雪，无情榆荚漫堆钱。","穷愁不服春辜负，酒病依还似去年。"]},{"t":"春暮答人吟","f":"七言绝句","c":["相违经岁意何如，漫说为邻德不孤。","咫尺洛阳春已尽，过从能忆旧时无。"]},{"t":"是夕宿至锦屏山下","f":"七言绝句","c":["寻常看月亦婵娟，不似今宵特地圆。","疑是素娥纾宿憾，相逢为在锦屏前。"]},{"t":"昼寝房","f":"七言绝句","c":["昼寝房中好避乖，中堂有客寄书来。","多因只是名和利，放向床头不拆开。"]},{"t":"洛阳春吟 其二","f":"七言绝句","c":["洛阳人惯见奇葩，桃李花开未当花。","须是牡丹花盛发，满城方始乐无涯。"]},{"t":"洛阳春吟 其四","f":"七言绝句","c":["光阴不肯略从容，九十日春还又空。","多少落花无著莫，半随流水半随风。"]},{"t":"洛阳春吟 其六","f":"七言绝句","c":["十日好花都去尽，可怜青帝用功深。","游人莫便无凭据，未必红芳胜绿阴。"]},{"t":"洛阳春吟 其一","f":"七言绝句","c":["四方景好无如洛，一岁花奇莫若春。","景好花奇精妙处，又能分付与闲人。"]},{"t":"洛阳春吟 其五","f":"七言绝句","c":["春归花谢日初长，燕语莺啼各自忙。","何故游人断来往，绿阴殊不减红芳。"]},{"t":"洛阳春吟 其八","f":"七言绝句","c":["用尽四时周一岁，唯春能见好花开。","十千买酒未为贵，既去红芳岂再来。"]},{"t":"相笑","f":"七言绝句","c":["白云耕叟说方知，遥指西南旧殿基。","更有笑人君不见，道傍桥是墓前碑。"]},{"t":"秋望吟","f":"五言绝句","c":["草色连云色，山光接水光。","危楼一百尺，旅雁两三行。"]},{"t":"胡越吟","f":"五言绝句","c":["胡越同心日，夫妻反目时。","人间无大小，得失在须斯。"]},{"t":"药轩","f":"七言绝句","c":["山里药多人不识，夫君移植更标名。","果能医得人间病，红紫何妨好近楹。"]},{"t":"诫子吟 其三","f":"五言绝句","c":["周孔不足法，轲雄不足师。","还同弃常膳，除是适海涯。"]},{"t":"诫子吟 其一","f":"七言绝句","c":["至宝明珠非有颣，全珍良玉自无瑕。","为珠为玉尚如此，何况为人多过差。"]},{"t":"诫子吟 其二","f":"五言绝句","c":["有过不能改，知贤不肯亲；","虽生人世上，未得谓之人。"]},{"t":"送猗氏张主簿","f":"七言绝句","c":["人间仕宦几千里，堂上亲闱别两重。","须念鹏飞从此始，方今路险善求容。"]},{"t":"阁上招友人","f":"五言绝句","c":["清风正蔼如，小阁枕通衢。","不欲久独擅，能来同享无。"]},{"t":"借出诗","f":"五言绝句","c":["诗狂书更逸，近岁不胜多。","大半落天下，未还安乐窝。"]},{"t":"夏日南园","f":"五言绝句","c":["夏木无重数，森阴翠樾低。","相呼百禽语，太半是黄鹂。"]},{"t":"悯旱","f":"七言绝句","c":["正要雨时须不雨，已成灾处更成灾。","如何百谷欲焦烂，遍地止存蒿与莱。"]},{"t":"秦川吟二首 其二","f":"七言绝句","c":["秦川两汉帝王区，今日关东作帝都。","多少圣贤存旧史，夕阳唯只见荒芜。"]},{"t":"秦川吟二首 其一","f":"七言绝句","c":["当时马上过秦川，倏忽于今二十年。","因见夫君话家住，依稀记得旧风烟。"]},{"t":"莫如吟 其一","f":"五言绝句","c":["亲莫如父子，远莫如蛮夷。","蛮夷和亦至，父子失须离。"]},{"t":"暮春吟","f":"七言绝句","c":["林下居常睡起迟，那堪车马近来稀。","春深昼永帘垂地，庭院无风花自飞。"]},{"t":"偶书吟","f":"五言绝句","c":["风林无静柯，风池无静波。","林池既不静，禽鱼当如何。"]},{"t":"偶得吟","f":"七言绝句","c":["人间事有难区处，人间事有难安堵。","有一丈夫不知名，静中只见闲挥麈。"]},{"t":"商山旅中作","f":"七言绝句","c":["残火昏灯夜正沉，默思前事拥寒衾。","霜天皎月虽千里，不抵伤时一寸心。"]},{"t":"商君吟","f":"七言绝句","c":["商鞅得君持法处，赵良终日正言时。","当其命令炎如火，车裂如何都不知。"]},{"t":"寄三城王宣徽二首 其二","f":"五言绝句","c":["路上尘方坌，壶中花正开。","何须头尽白，然后赋归来。"]},{"t":"寄三城王宣徽二首 其一","f":"五言绝句","c":["林下居虽陋，花前饮却频。","世间无事乐，都恐属闲人。"]},{"t":"寄三城旧友卫比部二绝 其二","f":"五言绝句","c":["景好身还健，天晴路又乾。","小车芳草软，处处是清欢。"]},{"t":"寄吴传正寺丞","f":"七言绝句","c":["天津风月一何孤，似我经秋相忆无。","每仗晴波寄声去，不知曾得到东都。"]},{"t":"寄寿安令簿尉诸君","f":"七言绝句","c":["锦屏山下好安栖，花月风烟未改移。","闻说近来长袖过，林前立马尽多时。"]},{"t":"寄前洛阳簿陆刚叔秘校","f":"七言绝句","c":["洛阳官满归吴会，男子雄图志未伸。","若到江山最佳处，举杯无惜望天津。"]},{"t":"寄亳州秦伯镇兵部 其六","f":"七言绝句","c":["酒涵花影满卮红，泻入天和胸臆中。","最爱一般情味好，半醺时与太初同。"]},{"t":"寄亳州秦伯镇兵部 其四","f":"七言绝句","c":["虽贫无害日高眠，人不堪忧我自便。","煅鍊物情时得意，新诗还有百来篇。"]},{"t":"寄亳州秦伯镇兵部 其五","f":"七言绝句","c":["天心复处是无心，心到无时无处寻。","若谓无心便无事，水中何故却生金。"]},{"t":"寄亳州秦伯镇兵部 其二","f":"七言绝句","c":["人事纷纷积有年，何烦颦蹙向花前。","万般计较头须白，饶了胸中不坦然。"]},{"t":"寄亳州秦伯镇兵部 其一","f":"七言绝句","c":["三川地正得中阳，气入奇葩亦自王。","善识好花人不远，好花无吝十分芳。"]},{"t":"寄亳州秦伯镇兵部 其三","f":"七言绝句","c":["无限有情风月间，好将醇酒发酡颜。","奈何人自生疑阻，利害嫌轻更设关。"]},{"t":"措处吟","f":"五言绝句","c":["在未定之时，当难处之地。","方事之危疑，见人之措置。"]},{"t":"晚晖亭","f":"七言绝句","c":["高亭新建碍烟霞，暮景能留是可嘉。","最近赏春来往路，游人应问是谁家。"]},{"t":"梦中吟","f":"五言绝句","c":["梦里常言梦，谁知觉后思。","不知今亦梦，更说梦中时。"]},{"t":"深秋吟","f":"五言绝句","c":["终岁都无事，四时长有花。","小车乘兴去，所到便如家。"]},{"t":"清夜吟","f":"五言绝句","c":["月到天心处，风来水面时。","一般清意味，料得少人知。"]},{"t":"盗伯吟 其一","f":"五言绝句","c":["盗伯窥财物，其心不虑他。","取时唯恐少，败后只嫌多。"]},{"t":"盛衰吟","f":"七言绝句","c":["势盛举头方偃蹇，气衰旋踵却嗟吁。","厚诬天下称贤者，天下何尝可厚诬。"]},{"t":"笺年老逢春八首 其七 只恐人间都未知","f":"五言绝句","c":["酒到醺酣处，花当烂漫时。","醺酣归酩酊，烂漫入离披。"]},{"t":"笺年老逢春八首 其三 年老才会惜芳菲","f":"五言绝句","c":["一岁正荣处，三春特盛时。","是花堪爱惜，况见好花枝。"]},{"t":"窥开吟 其一","f":"五言绝句","c":["物理窥开后，人情照破时。","一身都是我，瘦了又还肥。"]},{"t":"笺年老逢春八首 其八 自知一赏有分付","f":"五言绝句","c":["群卉争妍处，奇花独异时。","东君深意思，亦恐要人知。"]},{"t":"笺年老逢春八首 其六 这般意思难名状","f":"五言绝句","c":["阴阳初感处，天地未分时。","言语既难到，丹青何处施。"]},{"t":"笺年老逢春八首 其二 美酒饮教微醉后","f":"五言绝句","c":["瓮头喷液处，盏面起花时。","有客来相访，通名曰伏羲。"]},{"t":"笺年老逢春八首 其五 谁让万金无孑遗","f":"五言绝句","c":["白日偏催处，黄金欲尽时。","侈心都用了，始得一开眉。"]},{"t":"绳水吟","f":"七言绝句","c":["有水善平难善直，唯绳能直不能平。","如将绳水合为一，世上何忧事不明。"]},{"t":"野轩","f":"七言绝句","c":["一轩名野非尘境，嵩少烟岑送好风。","日月岁时都属已，更于何处觅壶中。"]},{"t":"善处吟","f":"五言绝句","c":["善处忧难作，能持事自修。","腹心无外物，蛮貊亦怀柔。"]},{"t":"善恶吟","f":"七言绝句","c":["君子学道则务本，小人见利则忘生。","务本则非礼不动，见利则非贿不行。"]},{"t":"富贵","f":"七言绝句","c":["富贵如将智力求，仲尼年少合封侯。","世人不解青天意，空使身心半夜愁。"]},{"t":"富贵吟","f":"七言绝句","c":["大舜与人同好恶，以人从欲得安乎。","能知富贵寻常事，富贵能骄非丈夫。"]},{"t":"悲喜吟","f":"五言绝句","c":["吴起初辞魏，张仪乍入秦。","西河蒙惠久，南楚受欺频。"]},{"t":"温良吟","f":"七言绝句","c":["君子温良当责备，小人情伪又须知。","因惊世上机关恶，遂觉壶中日月迟。"]},{"t":"痛矣吟","f":"五言绝句","c":["痛矣时难得，悲哉道未传。","今年年已尽，明日是明年。"]},{"t":"登石阁吟","f":"七言绝句","c":["一般情意恶难羁，长怕登高望远时。","今日凭栏异常日，几回将下又迟迟。"]},{"t":"答人吟 其二","f":"七言绝句","c":["初春洛城梅开时，赏梅更吟梅花诗。","梅花虽开难远寄，唯寄梅诗伸所思。"]},{"t":"答人吟 其一","f":"七言绝句","c":["谁道闲人无事权，事权唯只是诗篇。","四时雪月风花景，都与收来入近编。"]},{"t":"答人吟","f":"七言绝句","c":["筋骸得似当年否，气血能如旧日无。","却喜一般增长处，樽前谈笑有工夫。"]},{"t":"答人吟","f":"五言绝句","c":["林下闲言语，何须更问为。","自知无纪律，安得谓之诗。"]},{"t":"答宁秀才求诗吟","f":"五言绝句","c":["林下闲言语，何须要许多。","几乎三百首，足以备吟哦。"]},{"t":"答君实端明游寿安神林","f":"七言绝句","c":["占得幽栖一片山，都离尘土利名间。","四时分定所游处，不为移文便往还。"]},{"t":"答李希淳屯田三首 其三","f":"七言绝句","c":["胸中日月时舒惨，笔下风云旋合离。","老去无成尚如此，不知成后更何为。"]},{"t":"答李希淳屯田三首 其二","f":"七言绝句","c":["竹间水际情怀好，月下风前意思多。","洛社过从无事日，非吾数辈更谁何。"]},{"t":"答李希淳屯田三首 其一","f":"七言绝句","c":["去岁尝蒙远寄诗，当时已叹友朋希。","如今存者殆非半，不纵欢游待几时。"]},{"t":"答和吴传正赞善二首并寄高阳王十三机宜 其二","f":"五言绝句","c":["乐静岂无病，好闲终有心。","争如自得者，与世善浮沈。"]},{"t":"答和吴传正赞善二首并寄高阳王十三机宜 其一","f":"七言绝句","c":["洛阳城里一愚夫，十许年来不读书。","老去情怀难状处，淡烟寒月映松疏。"]},{"t":"缘饰吟","f":"七言绝句","c":["缘饰了时称好手，作为成处是真家。","须防冷眼人观觑，傀儡都无帐幕遮。"]},{"t":"谢开叔司封用无事无求得最多","f":"七言绝句","c":["客问人间事若何，尧夫对曰不知他。","居林之下行林下，无事无求得最多。"]},{"t":"谢王谏议见思吟","f":"七言绝句","c":["西斋前后半松筠，万虑澄馀始见真。","不谓天光明净处，又能时忆旧交亲。"]},{"t":"谢西台张元伯雪中送诗","f":"七言绝句","c":["洛城雪片大如手，炉中无火樽无酒。","凌晨有人来打门，言送西台诗一首。"]},{"t":"谢伯淳察院用先生不是打乖人","f":"七言绝句","c":["经纶事业须才者，燮理功夫有巨臣。","安乐窝中闲偃仰，焉知不是打乖人。"]},{"t":"谢判府王宣徽惠酒","f":"七言绝句","c":["自得花枝向远邻，只忧轻负一番春。","无何宠贶酒双榼，少室山人遂不贫。"]},{"t":"谢君实端明用只将花卉记冬春","f":"七言绝句","c":["有时自问自家身，莫是羲皇已上人。","日往月来都不记，只将花卉记冬春。"]},{"t":"谢君实端明惠山蔬八品","f":"七言绝句","c":["八品山蔬尽药萌，何山采得各标名。","山翁惊受霜台贶，即命山妻亲自烹。"]},{"t":"谢君实端明惠牡丹","f":"七言绝句","c":["霜台何处得奇葩，分送天津小隐家。","初讶山妻忽惊走，寻常只惯插葵花。"]},{"t":"谢寿安簿寄锦屏山下所失剪刀","f":"七言绝句","c":["江夏尚能悲坠履，少原唯解泣遗簪。","一刀所失安足系，不那久经人用心。"]},{"t":"谢郑守王密学惠酒","f":"七言绝句","c":["堂堂大府来新酒，密密小园开好花。","此日饮之红树下，还惊不称野人家。"]},{"t":"谢彦国相公和诗用醉和风雨夜深归","f":"七言绝句","c":["道堂闲话尽多时，尘外杯觞不浪飞。","初上小车人已静，醉和风雨夜深归。"]},{"t":"谢商守宋郎中寄到天柱山户帖仍依元韵 其一","f":"七言绝句","c":["商于飞到一符新，遂已平生分外亲。","尤喜紫芝先入手，西南天柱与天邻。"]},{"t":"谢商守宋郎中寄到天柱山户帖仍依元韵 其三","f":"七言绝句","c":["不将生杀奏严宸，却抱烟岚学隐沦。","多谢史君虚右席，重延天柱一山人。"]},{"t":"谢商守宋郎中寄到天柱山户帖仍依元韵 其二","f":"七言绝句","c":["初心本欲践臣邻，帝里司回斗柄春。","今日得居天柱下，不忧先有夜行人。"]},{"t":"谢商守宋郎中寄到天柱山户帖仍依元韵 其四","f":"七言绝句","c":["一簇烟岚锁乱云，孤高天柱好栖真。","从今便作西归计，免向人间更问津。"]},{"t":"道装吟 其二","f":"七言绝句","c":["道家仪用此巾衣，师外曾闻更拜谁。","何故尧夫须用拜，安知人不是吾师。"]},{"t":"道装吟 其一","f":"七言绝句","c":["道家仪用此衣巾，只拜星辰不拜人。","何故尧夫须用拜，安知人不是星辰。"]},{"t":"道装吟 其四","f":"七言绝句","c":["如知道只在人心，造化功夫自可寻。","若说衣巾便为道，尧夫何者敢披襟。"]},{"t":"道装吟 其三","f":"七言绝句","c":["安车麈尾道衣装，里闬过从乃是常。","闻说洞天多似此，吾乡殊不异仙乡。"]},{"t":"量力吟","f":"七言绝句","c":["量力动时无悔吝，随宜乐处省营为。","须求骐骥方乘马，亦恐终身无马骑。"]},{"t":"感事吟","f":"七言绝句","c":["蛇头蝎尾不相同，毒杀人多始是功。","风月四时无限好，莫将闲事挠胸中。"]},{"t":"感雪吟","f":"七言绝句","c":["旨酒嘉肴与管弦，通宵鼎沸乐丰年。","侯门深处还知否，百万流民在露天。"]},{"t":"禁烟留题锦屏山下四首 其四","f":"七言绝句","c":["春半花开百万般，东风近日恶摧残。","可怜桃李性温厚，吹尽都无一句言。"]},{"t":"禁烟留题锦屏山下四首 其三","f":"七言绝句","c":["无涯桃李待清明，经岁方能开得成。","不念化工曾著力，狂风何故苦相凌。"]},{"t":"禁烟留题锦屏山下四首 其二","f":"七言绝句","c":["寒食风烟锦屏下，凭高把酒兴何如。","满川桃李方妍媚，不忍重为风破除。"]},{"t":"禁烟留题锦屏山下四首 其一","f":"七言绝句","c":["满川桃李弄芳妍，不忍重为风所残。","忍使一年春遂去，尽凭高处与盘桓。"]},{"t":"窥开吟 其十","f":"五言绝句","c":["物理窥开后，人情照破休。","止堪初看望，不可久延留。"]},{"t":"题四皓庙四首 其四","f":"七言绝句","c":["田横入海犹能得，商至长安百里强。","能使四人成美节，始知高祖是真王。"]},{"t":"题四皓庙四首 其三","f":"七言绝句","c":["汉皇傲物终难屈，太子卑辞方肯出。","虽老犹能成大功，至今高义如星日。"]},{"t":"题四皓庙四首 其二","f":"七言绝句","c":["灞上真人既已翔，四人相顾都无语。","徐云天命自有归，不若追踪巢与许。"]},{"t":"题四皓庙四首 其一","f":"七言绝句","c":["强秦失御血横流，天下求君君不有。","正是英雄较逐时，未知鹿入何人手。"]},{"t":"题淮阴侯庙十首 其十","f":"七言绝句","c":["若履暴荣须暴辱，既经多喜必多忧。","功成能让封王印，世世长为列土侯。"]},{"t":"题淮阴侯庙十首 其九","f":"七言绝句","c":["韩信恃功前虑寡，汉皇负德尚权安。","幽囚必欲擒来斩，固要加诸甚不难。"]},{"t":"题淮阴侯庙十首 其八","f":"七言绝句","c":["汉家基定议功勋，异姓封王有五人。","不似淮阴最雄杰，敢教根固又生秦。"]},{"t":"题淮阴侯庙十首 其七","f":"七言绝句","c":["若非韩信难除项，不得萧何莫制韩。","天下须知无一手，苟非高祖用萧难。"]},{"t":"题淮阴侯庙十首 其六","f":"七言绝句","c":["虽则有才兼有智，存亡进退处非真。","五湖依旧烟波在，范蠡无人继后尘。"]},{"t":"题淮阴侯庙十首 其五","f":"七言绝句","c":["韩信事刘元不叛，萧何惑汉竟生疑。","当初若听蒯通语，高祖功名未可知。"]},{"t":"题淮阴侯庙十首 其四","f":"七言绝句","c":["一时韩信为良犬，千古萧何作霸臣。","彼此并干名教罪，罪犹不逮谓斯人。"]},{"t":"题淮阴侯庙十首 其三","f":"七言绝句","c":["生身既得逢真主，立事何须作假王。","谁谓祸阶从此始，不宜回首怨高皇。"]},{"t":"题淮阴侯庙十首 其二","f":"七言绝句","c":["据立大功非不智，复贪王爵似专愚。","造成四百年炎汉，才得安宁反受诛。"]},{"t":"题淮阴侯庙十首 其一","f":"七言绝句","c":["一身作乱宜从戮，三族全夷似少恩。","汉道是时初杂霸，萧何王佐殆非尊。"]},{"t":"题黄河","f":"七言绝句","c":["谁言为利多于害，我谓长浑未始清。","西至昆崙东至海，其间多少不平声。"]},{"t":"懒起吟","f":"七言绝句","c":["半记不记梦觉后，似愁无愁情倦时。","拥衾侧卧未忺起，帘外落花撩乱飞。"]},{"t":"瀍河上观杏花回","f":"七言绝句","c":["瀍河东看杏花开，花外天津暮却回。","更把杏花头上插，图人知道看花来。"]},{"t":"簪花吟","f":"七言绝句","c":["簪花犹且强年少，诉酒固非佯小心。","花好酒嘉情更好，奈何明日病还深。"]},{"t":"二十九日依韵和洛阳陆刚叔主簿见赠","f":"七言律诗","c":["一霎萧萧晚雨馀，凤凰楼下偶驱车。","郤诜片玉知能忆，乐广青天幸未疏。","相阔夏秋闻甚事，可亲灯火读何书。","恨无束帛嘉程子，徒自悁悁返弊庐。"]},{"t":"二十五日依韵和左藏吴传正寺丞见赠","f":"七言律诗","c":["上阳光景好看书，非象之中有坦途。","良月引归芳草渡，快风飞过洞庭湖。","不因赤水时时往，焉有黄芽日日娱。","莫道天津便无事，也须闲处著功夫。"]},{"t":"二月吟","f":"五言律诗","c":["林下故无知，唯知二月期。","酒尝新熟后，花赏半开时。","只有醺酣趣，殊无烂漫悲。","谁能将此景，长贮在心脾。"]},{"t":"人生长有两般愁","f":"七言律诗","c":["人生长有两般愁，愁死愁生未易休。","或向利中穷力取，或于名上尽心求。","多思唯恐晚得手，未老已闻先白头。","我有何功居彼上，其间掉臂独无忧。"]},{"t":"十六日依韵酬福昌令有寄","f":"七言律诗","c":["道义相欢岂易亲，古称难处是知人。","文章不结市朝士，荣辱非关云水身。","话入精详皆物理，言无形迹尽天真。","他时洛社过从辈，图牒中添又一邻。"]},{"t":"十分吟 其二","f":"五言律诗","c":["所谓十分人，须有十分事。","事苟不十分，终是未完备。","事父尽其心，事兄尽其意。","事君尽其忠，事师尽其义。"]},{"t":"又旋风吟二首 其二","f":"七言律诗","c":["自是尧夫不善琴，非关天下少知音。","老年难做少年事，年少不知年老心。","将养精神便静坐，调停意思喜清吟。","如何医药不寻访，近日衰躯有病侵。"]},{"t":"又旋风吟二首 其一","f":"七言律诗","c":["近日衰躯有病侵，如何医药不求寻。","轩前密叶自成幄，砌下黄花空散金。","闲看蜜蜂收蜜意，静观巢燕垒巢心。","非关天下知音少，自是尧夫不善琴。"]},{"t":"三十年吟","f":"七言律诗","c":["三十年间更一世，其间堪笑复堪愁。","天生天杀何尝尽，人是人非殊未休。","善偶鸳鸯头早白，能啼杜宇血先流。","须知却被才为害，及至无才又却忧。"]},{"t":"上寺看南山","f":"五言律诗","c":["叠叠是峰峦，西连梁雍宽。","与其行里看，不若坐中观。","包括经唐汉，并吞历晋韩。","消沉事难问，唯尔尚巑岏。"]},{"t":"乞笛竹栽于李少保宅","f":"七言律诗","c":["浪种闲花占地生，未尝容易暂留情。","奈何苦爱凌霜节，况是犹存镂管名。","待凤至时当有实，学龙吟处岂无声。","幽人愿乞数枝种，得自君家又更荣。"]},{"t":"小车吟","f":"词","c":["自从三度绝韦编，不读书来十二年。","大?子中消白日，小车儿上看青天。","闲为水竹云山主，静得风花雪月权。","俯仰之间无所愧，任他人谤似神仙。"]},{"t":"小春天","f":"五言律诗","c":["八月小春天，如人强少年。","偷生诚有谓，却老固无缘。","既有神仙术，能回草木妍。","安知太平日，不得似尧天。"]},{"t":"小圃睡起","f":"五言律诗","c":["门外似深山，天真信可还。","轩裳奔走外，日月往来间。","有水园亭活，无风草木闲。","春禽破幽梦，枝上语绵蛮。"]},{"t":"川上观鱼","f":"五言律诗","c":["天气冷涵秋，川长鱼正游。","虽知能避网，犹恐误吞钩。","已绝登门望，曾无点额忧。","因思濠上乐，旷达是庄周。"]},{"t":"川上怀旧四首 其四","f":"五言律诗","c":["地迥川原阔，村孤烟水闲。","雷轻龙过浦，云乱雨移山。","田者荷锄去，渔人背网还。","伊予独沾湿，犹在道途间。"]},{"t":"中和吟","f":"五言律诗","c":["性亦故无他，须是识中和。","心上语言少，人间事体多。","如霖回久旱，似药起沉痾。","一物尚不了，其如万物何。"]},{"t":"中秋月","f":"七言律诗","c":["一年一度中秋夜，十度中秋九度阴。","求满直须当夜半，要明仍候到天心。","无云照处情非浅，不睡观时意更深。","徒爱古人诗句好，何堪千里共如今。"]},{"t":"为人吟","f":"七言律诗","c":["为人须是与人群，不与人群不尽人。","大舜与人焉有异，帝尧亲族亦推伦。","人心龃龉一身病，事体和谐四海春。","心在四支心是主，四支又复远于身。"]},{"t":"为客吟 其三","f":"七言律诗","c":["忽忆东吴为客日，当年意气乐从游。","登山未始等闲辍，饮酒何尝容易休。","万柄荷香经楚甸，一帆风软过扬州。","追思何异邯郸梦，瞬息光阴三十秋。"]},{"t":"为客吟 其二","f":"七言律诗","c":["忽忆东朐为客日，壮心初见水云乡。","岛夷居处邻荒服，潮水来时杂海商。","卧看苍溟围大块，坐观红日出扶桑。","虚生虚死人何限，男子之称不易当。"]},{"t":"为客吟 其一","f":"七言律诗","c":["忽忆南秦为客日，洛阳东望隔秦川。","云山去此二千里，岁月于今十九年。","柳色得非新婀娜，江声应是旧潺湲。","衰躯设使能重往，畴昔情怀奈杳然。"]},{"t":"为善吟","f":"五言律诗","c":["人之为善事，善事义当为。","金石犹能动，鬼神其可欺。","事须安义命，言必道肝脾。","莫问身之外，人知与不知。"]},{"t":"书事吟","f":"七言律诗","c":["他山有石能攻玉，玉未全成老已催。","有限光阴随事去，无涯衰朽逐人来。","陶镕情性诗千首，燮理筋骸酒一杯。","六十六年无事日，心源方始似昭回。"]},{"t":"仁者吟","f":"七言律诗","c":["仁者难逢思有常，平居慎勿恃无伤。","争先径路机关恶，近后语言滋味长。","爽口物多须作疾，快心事过必为殃。","与其病后能求药，不若病前能自防。"]},{"t":"六十二吟","f":"七言律诗","c":["行年六十二康强，况复身居永熟乡。","道德生辰非易得，浅斟低唱又何妨。","无涯岁月难拘管，有限形骸莫毁伤。","多少英雄弄才智，大曾经过恶思量。"]},{"t":"六十三吟","f":"七言律诗","c":["行年六十有三岁，齿发虽衰志未衰。","耻把精神虚作弄，肯将才力妄施为。","愁闻刮骨声音切，闷见吹毛智数卑。","珍重至人尝有语，落便宜是得便宜。"]},{"t":"内乡兼隐亭","f":"五言律诗","c":["兼隐诧来书，于时特起予。","民淳无讼听，县僻类山居。","簿领杯盘外，官联谈笑馀。","不知当此际，傍邑更谁如。"]},{"t":"天地吟","f":"七言律诗","c":["天人之际岂容针，至理何烦远去寻。","凶焰炽时焚更烈，恩波流处浸还深。","长征戍卒思归意，久旱苍生望雨心。","祸福转来如反掌，可能中夜不沉吟。"]},{"t":"天宫小阁倚栏","f":"七言律诗","c":["六尺残躯病复羸，况堪日日更添衰。","满怀可惜精明处，一语未能分付时。","沙里有金然索拣，石中韫玉奈何疑。","此情牢落西风暮，倚遍栏干人不知。"]},{"t":"天津闲步","f":"五言律诗","c":["天子旧神州，葱葱气象浮。","园林闲近水，殿阁远横秋。","浪雪暑犹在，桥虹晴不收。","人间无事日，此地好淹留。"]},{"t":"天津幽居","f":"五言律诗","c":["予家洛城里，况复在天津。","日近先知晓，天低易得春。","时光优化国，景物厚幽人。","自可辞轩冕，闲中老此身。"]},{"t":"天道吟","f":"五言律诗","c":["天道不难知，人情未易窥。","虽闻言语处，更看作为时。","隐几功夫大，挥戈事业卑。","春秋赖乘兴，出用小车儿。"]},{"t":"无行吟","f":"五言律诗","c":["无行少年子，京都来往频。","功名一生事，歌酒十年春。","有数黄金尽，无情白发新。","朋从消散尽，赢得病随身。"]},{"t":"无苦吟","f":"五言律诗","c":["平生无苦吟，书翰不求深。","行笔因调性，成诗为写心。","诗扬心造化，笔发性园林。","所乐乐吾乐，乐而安有淫。"]},{"t":"月夜","f":"五言律诗","c":["雨霁风自好，秋深天未寒。","移床就阶下，看月出林端。","有酒欲共饮，无宾可同欢。","他时遇良友，此景复求难。"]},{"t":"月窟吟","f":"五言律诗","c":["月窟与天根，中间来往频。","所居皆绰绰，何往不伸伸。","投足自有定，满怀都是春。","若无诗与酒，又似太亏人。"]},{"t":"毛头吟 其二","f":"七言律诗","c":["忧国心深为爱君，爱君须更重于身。","口中讲得未必是，手里做成方始真。","妄意动时难照物，俗情私处莫知人。","厚诬天下凶之甚，多少英才在下尘。"]},{"t":"长子伯温失解以诗示之","f":"五言律诗","c":["儒家所尚者，行善与文章。","用舍何尝定，枯荣未易量。","干求便黾勉，得失是寻常。","外物不可必，其言味甚长。"]},{"t":"长忆乍能言","f":"五言律诗","c":["长忆乍能言，朝游父母前。","方行初下膝，既老遂华颠。","在昔四五岁，于今六十年。","却看儿女戏，又喜又潸然。"]},{"t":"世上吟","f":"七言律诗","c":["世上偷闲始得闲，我生长在不忙间。","光阴有限同归老，风月无涯可慰颜。","坐卧绕身唯水竹，登临满目但云山。","醉眠只就花阴下，转破花阴梦始还。"]},{"t":"东轩消梅初开劝客酒二首 其二","f":"七言律诗","c":["春色融融满洛城，莫辞行乐慰平生。","深思闲友开眉笑，重惜梅花照眼明。","况是山翁差好事，可怜芳酒最多情。","此时不向樽前醉，更向何时醉太平。"]},{"t":"东轩消梅初开劝客酒二首 其一","f":"七言律诗","c":["为爱消梅胜早梅，数枝先发日徘徊。","若教岭表腊前尽，安有洛阳正后开。","香逐暖风初出谷，艳随芳酒正浮醅。","佳宾会取东君意，莫负乘春此际来。"]},{"t":"代书寄广信李遵度承制","f":"五言律诗","c":["蓟北更千里，汉唐为极边。","奈何今境土，不复旧山川。","虎帐兵家重，雕弓嗣子传。","他年勒功处，无使后燕然。"]},{"t":"代书寄友人","f":"七言律诗","c":["当年有志高天下，尝读前书笑谢安。","岂谓此身甘老朽，尚无闲地可盘桓。","棋逢敌手才堪着，琴少知音不愿弹。","非止不才能退默，古贤长恨得时难。"]},{"t":"代书寄北海幕赵充道太博","f":"七言律诗","c":["自从终鲜罢吟哦，聊为临风一浩歌。","别易会难情不已，登高望远兴如何。","百年可惜时无再，千里相思事更多。","今日樽罍真北海，况君雅重几人过。"]},{"t":"代书寄白波张景真辇运","f":"七言律诗","c":["秋入山河气象雄，不堪闲望老年中。","金兰契重思无限，手足情多感未终。","半局残棋销白昼，一簪华发乱西风。","唯君父子相知久，松桂心同色更同。"]},{"t":"代书寄吴传正寺丞","f":"七言律诗","c":["敦笃情怀世所稀，昔年今日事难追。","雪霜未始寒无甚，松桂何尝色暂移。","洛邑士人虽我信，天津风月只君知。","梦魂不悟东都远，依旧过从似旧时。"]},{"t":"代书寄前洛阳簿陆刚叔秘校","f":"七言律诗","c":["洛城官满振衣裾，尘土何由浼远途。","道在幸逢清日月，眼明应见旧江湖。","知行知止唯贤者，能屈能伸是丈夫。","归去何妨趁残水，三吴还似向时无。"]},{"t":"代书寄剑州普安令周士彦屯田 其一","f":"七言律诗","c":["作官休用叹奚为，未有升高不自卑。","君子屈伸方为道，吾儒进退贵从宜。","即今彭泽归何地，他日东门去未迟。","痛恨伊嵩景无限，一名佳处重求资。"]},{"t":"代书寄商洛令陈成伯","f":"七言律诗","c":["此去替期犹半岁，商山穷僻少医名。","感伤多后风防滞，暑湿偏时疾易生。","圣智不能无蹇剥，贤才方善处哀荣。","斯言至浅理非浅，少补英豪一二明。"]},{"t":"代书寄程正叔","f":"七言律诗","c":["严亲出守剑门西，色养欢深世表仪。","唐相规模今历历，蜀民遨乐旧熙熙。","海棠洲畔停桡处，金雁桥边立马时。","料得预忧天下计，不忘君者更为谁。"]},{"t":"代书寄鄞江知县张太博","f":"七言律诗","c":["长忆当年扫弊庐，弟兄同受策名初。","一生不记寻常事，千里犹通咫尺书。","风月遥知四明好，江山况是九秋馀。","片帆未得闲飞去，徒见严君问起居。"]},{"t":"代书寄濠倅张都官","f":"七言律诗","c":["多惭吾亦未知音，天乐虽闻不许寻。","惠子相时情自好，庄生游处意能深。","闲来略记一春事，老去难忘千里心。","洛社交朋每相见，为吾因掉白头吟。"]},{"t":"代书答开封府推官姚辅周郎中","f":"七言律诗","c":["世态其如与愿违，必须言进是无知。","遍将底事闲思处，不若西街极论时。","设有奇才能动世，奈何双鬓已如丝。","天边新月从来细，不为人间爱画眉。"]},{"t":"代书答朝中旧友","f":"五言律诗","c":["少日治文章，亦曾观国光。","山林虽不返，畎亩未尝忘。","麋鹿宁无志，鹓鸿自有行。","还知今日事，大故索思量。"]},{"t":"击壤吟","f":"七言律诗","c":["人言别有洞中仙，洞里神仙恐妄传。","若俟灵丹须九转，必求朱顶更千年。","长年国里花千树，安乐窝中乐满悬。","有乐有花仍有酒，却疑身是洞中仙。"]},{"t":"击壤吟","f":"五言律诗","c":["击壤三千首，行窝二十家。","乐天为事业，养志是生涯。","出入将如意，过从用小车。","人能知此乐，何必待纷华。"]},{"t":"半醉吟 其二","f":"五言律诗","c":["半醉小车行，世间无此荣。","凉风迎面细，垂柳拂头轻。","意若兼三事，情如拥万兵。","这般闲富贵，料得没人争。"]},{"t":"头风吟","f":"七言律诗","c":["近日头风不奈何，未妨谈笑与高歌。","人才相去不甚远，事体所争能许多。","闭目面前都是暗，开怀天外更无他。","若由智数经营得，大有英雄善揣摩。"]},{"t":"对花","f":"五言律诗","c":["花枝照酒卮，把酒嘱花枝。","酒尽钱能买，花残药不医。","人无先酩酊，花莫便离披。","慢慢对花饮，况春能几时。"]},{"t":"对花饮","f":"七言律诗","c":["人言物外有烟霞，物外烟霞岂足誇。","若用校量为乐事，但无忧挠是仙家。","百年光景留难住，十日芳菲去莫遮。","对酒有花非负酒，对花无酒是亏花。"]},{"t":"对酒吟","f":"七言律诗","c":["有酒时时泛一瓯，年将七十待何求。","齿衰婚嫁尚未了，岁旱田园才薄收。","客去有时闲拱手，日高无事静梳头。","霜毛不止装诗景，更可因而入画休。"]},{"t":"白头吟","f":"五言律诗","c":["何人头不白，我白不因愁。","只被人多欲，其如我不忧。","不忧缘不动，多欲为多求。","年老人常事，如何不白头。"]},{"t":"立秋日川上作","f":"五言律诗","c":["富贵固难爱，贫寒易得愁。","休将少时态，移作老年羞。","既有非常乐，须防不次忧。","谁能保终始，长作国公侯。"]},{"t":"仿康节先生诗","f":"七言律诗","c":["每日清晨一炷香，谢天谢地谢三光。","所求处处田禾热，惟愿人人寿命长。","国有贤臣安社稷，家无逆子恼爹娘。","四方平静干戈息，我若贫时也不妨。"]},{"t":"训世孝弟诗十首 其一","f":"楚辞体","c":["子孝亲兮弟敬哥，训贤妯娌事翁婆。","好遵孟母三迁教，须读张公百忍歌。","孝友睦姻兼任恤，智仁圣义与中和。","当时曾子同杨博，子孝亲兮弟敬哥。"]},{"t":"训世孝弟诗十首 其二","f":"楚辞体","c":["子孝亲兮弟敬哥，莫因微利遽伤和。","黄金匮内休嫌少，阴德冥中要积多。","私曲岂知公直在，刚强无奈善柔何。","古今简籍多名誉，子孝亲兮弟敬哥。"]},{"t":"训世孝弟诗十首 其三","f":"楚辞体","c":["子孝亲兮弟敬哥，休伤和气忿争多。","偏生嫉妒偏艰窘，暗积私房暗折磨。","不孝自然生忤逆，无仁实是出妖魔。","但闻孝弟传千古，子孝亲兮弟敬哥。"]},{"t":"训世孝弟诗十首 其四","f":"楚辞体","c":["子孝亲兮弟敬哥，怡声下气与谦和。","难兄难弟名偏重，孝子贤孙贵自多。","负米尚难为薄养，读书宁不擢高科。","仲由陈纪皆如此，子孝亲兮弟敬哥。"]},{"t":"训世孝弟诗十首 其五","f":"楚辞体","c":["子孝亲兮弟敬哥，休残骨肉起风波。","劬劳恩重须当报，手足情深要取和。","公艺同居今古罕，田真共处子孙多。","如斯遐迩皆称美，子孝亲兮弟敬哥。"]},{"t":"训世孝弟诗十首 其六","f":"楚辞体","c":["子孝亲兮弟敬哥，天时地利与人和。","莫言世事常如此，堪叹人生有几何。","满眼繁华何足贵，一家安乐值钱多。","奇哉让梨并怀橘，子孝亲兮弟敬哥。"]},{"t":"龙门石楼看伊川","f":"七言律诗","c":["数朝从款走烟霞，纵意凭栏看物华。","百尺楼台通鸟道，一川烟水属僧家。","直须心逸方为乐，始信官荣未足誇。","此景得游无事日，也宜知幸福无涯。"]},{"t":"龙门道中作","f":"七言律诗","c":["物理人情自可明，何尝戚戚向平生。","卷舒在我有成算，用舍随时无定名。","满目云山俱是乐，一毫荣辱不须惊。","侯门见说深如海，三十年来掉臂行。"]},{"t":"仲尼吟","f":"七言律诗","c":["仲尼生鲁在吾先，去圣千馀五百年。","今日谁能知此道，当时人自比于天。","皇王帝伯中原主，父子君臣万世权。","河不出图吾已矣，修经意思岂徒然。"]},{"t":"伊川吟","f":"七言律诗","c":["休嗟流年随逝水，但将清景逐闲情。","山河天下从来广，日月林间长自明。","幸有园林供笑傲，岂无诗酒乐升平。","如何更得烟霞侣，好向伊川老此生。"]},{"t":"伤二舍弟无疾而化 其二","f":"七言律诗","c":["肠断东篱何所寻，东篱从此事沉沉。","差肩行处皆成往，吊影伤时无似今。","清泪已乾情莫极，黄泉未到恨非深。","不知何日能销尽，三十二年雍睦心。"]},{"t":"伤二舍弟无疾而化 其一","f":"七言律诗","c":["手足情深不可忘，割心犹未比其伤。","急难畴昔尔相济，终鲜如今我遂当。","韡韡棣开无并萼，邕邕雁去破初行。","自兹明月清风夜，萧索东篱看断肠。"]},{"t":"伤足","f":"五言律诗","c":["灾由无妄得，为患固非深。","乖已摄生理，贻亲忧虑心。","乍然艰步履，偶尔阻登临。","逾月方能出，难忘乐正箴。"]},{"t":"共城十吟 其七 春郊雨中","f":"五言律诗","c":["九野散漫漫，连昏鸟道间。","坐中迷远树，门外失前山。","袯襫耕夫喜，屏幪居者閒。","骚人正凝黯，天际意初还。"]},{"t":"共城十吟 其九 春郊旧酒","f":"五言律诗","c":["花开风雨后，忍病欲消磨。","未是疏狂极，其如困顿何。","梁间新燕乱，天外去鸿多。","总是灰心事，冥焉昼午过。"]},{"t":"共城十吟 其二 春郊閒步","f":"五言律诗","c":["病起复惊春，携筇看野新。","水边逢钓者，垄上见耕人。","访彼形容苦，酬予家业贫。","自惭功济力，未得遂生民。"]},{"t":"共城十吟 其八 春郊雨后","f":"五言律诗","c":["雨歇荡馀春，天光露太真。","茵铺芳草软，锦濯烂花新。","风触莺簧健，烟舒柳带匀。","如何当此景，閒卧度昌辰。"]},{"t":"共城十吟 其十 春郊花落","f":"五言律诗","c":["春暮多风雨，离披满后园。","晓馀残片拥，晴外乱红翻。","香径难留裛，娇心绝弄繁。","成蹊是桃李，狼籍尚无言。"]},{"t":"共城十吟 其六 春郊晚望","f":"五言律诗","c":["风暖啭鸣禽，天低薄薄阴。","烟容凝垄曲，雨意弄河心。","柳隔高城远，花藏旧县深。","独怜身卧病，犹许后春寻。"]},{"t":"共城十吟 其四 春郊花开","f":"五言律诗","c":["桃李正芬敷，花繁覆敝庐。","乱香寻密牖，碎影下前除。","静绕昼眠后，轻攀春醉馀。","纵然观尽日，谁敢罪狂疏。"]},{"t":"再和王不疑少卿见赠","f":"五言律诗","c":["乍凉天气好，何处不堪游。","鸿雁来宾日，鹰鹯得志秋。","忘形终夕乐，失脚一生休。","多少江湖上，舟船未到头。"]},{"t":"同王胜之学士转运赏西园芍药","f":"七言律诗","c":["此物扬州素所闻，今于洛汭特称珍。","雅知国色善移物，更著天香暗结人。","欲殿群芳仍占夏，得专奇品不须春。","日斜立马将归去，再倚朱栏看一巡。"]},{"t":"名利吟","f":"七言律诗","c":["名利到头非乐事，风波终久少安流。","稍邻美誉无多取，才近清欢与剩求。","美誉既多须有患，清欢虽剩且无忧。","滔滔天下曾知否，覆辙相寻卒未休。"]},{"t":"后园即事三首 其三","f":"七言律诗","c":["年来得疾号诗狂，每度诗狂必命觞。","乐道襟怀忘检束，任真言语省思量。","宾朋款密过从久，云水优闲兴味长。","始信渊明深意在，北窗当日比羲皇。"]},{"t":"后园即事三首 其二","f":"七言律诗","c":["天养疏慵自有方，洛城分得水云乡。","不闻世上风波险，但见壶中日月长。","一局闲棋留野客，数杯醇酒面脩篁。","物情悟了都无事，未学颜渊已坐忘。"]},{"t":"后园即事三首 其一","f":"七言律诗","c":["太平身老复何忧，景爱家园自在游。","几树绿杨阴乍合，数声幽鸟语方休。","竹侵旧径高低迸，水满春渠左右流。","借问主人何似乐，答云殊不异封侯。"]},{"t":"团团吟","f":"五言律诗","c":["如鉴又如钩，回旋莫记秋。","难穷天上理，易白世间头。","团处人人喜，亏时物物愁。","有生无不喘，何必待吴牛。"]},{"t":"安乐窝中四长吟","f":"七言律诗","c":["安乐窝中快活人，闲来四物幸相亲。","一编诗逸收花月，一部书严惊鬼神。","一炷香清冲宇泰，一樽酒美湛天真。","太平自庆何多也，唯愿君王寿万春。"]},{"t":"安乐窝中自贻","f":"七言律诗","c":["物如善得终为美，事到巧图安有公。","不作风波于世上，自无冰炭到胸中。","灾殃秋叶霜前坠，富贵春华雨后红。","造化分明人莫会，枯荣消得几何功。"]},{"t":"安乐窝中吟 其十二","f":"七言律诗","c":["生为男子偶昌辰，安乐窝中富贵身。","大字写诗誇壮健，小杯饮酒惜轻醇。","山川澄净初经雨，草木暄妍正遇春。","造化功夫精妙处，都宜分付与闲人。"]},{"t":"安乐窝中吟 其三","f":"七言律诗","c":["安乐窝中弄旧编，旧编将绝又重联。","灯前烛下三千日，水畔花间二十年。","有主山河难占籍，无争风月任收权。","闲吟闲咏人休问，此个功夫世不传。"]},{"t":"安乐窝中吟 其四","f":"七言律诗","c":["安乐窝中万户侯，良辰美景忍虚休。","已曾得手春深日，更欲披衣年老头。","晓露重时花满槛，暖醅浮处酒盈瓯。","圣人吃紧些儿事，又省工夫又省忧。"]},{"t":"安乐窝中吟 其九","f":"七言律诗","c":["安乐窝中甚不贫，中间有榻可容身。","儒风一变至于道，和气四时长若春。","日月作明明主日，人言成信信由人。","唯人与日不相远，过此何尝更语真。"]},{"t":"安乐窝中吟 其十一","f":"七言律诗","c":["安乐窝中春欲归，春归忍赋送春诗。","虽然春老难牵复，却有夏初能就移。","饮酒莫教成酩酊，赏花慎勿至离披。","人能知得此般事，焉有闲愁到两眉。"]},{"t":"尧夫何所有","f":"五言律诗","c":["尧夫何所有，一色得天和。","夏住长生洞，冬居安乐窝。","莺花供放适，风月助吟哦。","窃料人间乐，无如我最多。"]},{"t":"岁杪吟","f":"五言律诗","c":["一日去一日，一年添一年。","饶教成大器，其那已华颠。","志意虽依旧，聪明不及前。","若非心有得，亦恐学神仙。"]},{"t":"岁除吟","f":"五言律诗","c":["半百已华颠，如今更皓然。","自知为士子，人讶学神仙。","风月难忘酒，云山不著钱。","行年六十六，明日又添年。"]},{"t":"年老吟","f":"七言律诗","c":["岁华头上不能惊，唯有交亲眼更明。","皓皓月常因坐看，深深酒不为愁倾。","苟于心上无先觉，却似人间小后生。","欲约何人为伴侣，江湖泛去一舟轻。"]},{"t":"年老逢春十三首 其十三","f":"七言律诗","c":["年老逢春认破春，破春不用苦伤神。","身心自有安存地，草木焉能媚惑人。","此日荣为他日瘁，今年陈是去年新。","世间忧喜常相逐，多少酒能平得君。"]},{"t":"年老逢春十三首 其十二","f":"七言律诗","c":["年老逢春春不任，不任缘被老来侵。","一身老去恶足惜，满眼春归何处寻。","红日坠时风更急，落花流处水仍深。","流莺不悟芳菲歇，犹向枝头送好音。"]},{"t":"年老逢春十三首 其十一","f":"七言律诗","c":["年老逢春莫惜狂，惜狂无那兴难当。","园林恰到恶明媚，风雨便多闲中伤。","花等半开宜速赏，酒闻才熟便先尝。","大都美物天长惜，非是吾侪曲主张。"]},{"t":"年老逢春十三首 其十","f":"七言律诗","c":["年老逢春兴未收，愿春慈造少迟留。","既称好事愁花老，须与多情秉烛游。","酒里功劳闲汗马，诗中罪过静风流。","东君不奈人嘲戏，僝僽花枝恶未休。"]},{"t":"年老逢春十三首 其九","f":"七言律诗","c":["年老逢春莫厌频，更频能见几回春。","须将酒盏强留客，却恐花枝解笑人。","世态不堪新间旧，物情难免假疑真。","谁云梁燕多言语，此个深冤都未伸。"]},{"t":"年老逢春十三首 其八","f":"七言律诗","c":["年老逢春春莫悭，春悭不当世艰难。","四时只有三春好，一岁都无十日闲。","酒盏不烦人诉免，花枝须念雨摧残。","却愁千片飘零后，多少金能买此欢。"]},{"t":"年老逢春十三首 其七","f":"七言律诗","c":["年老逢春春莫厌，春工慎勿致猜嫌。","红芳若得眼前过，白发任从头上添。","雨后艳花零泪颗，风馀新月露眉尖。","轻醇酒面斟来凸，举盏长忧不易拈。"]},{"t":"年老逢春十三首 其六","f":"七言律诗","c":["年老逢春春意多，波光谁染柳谁搓。","池亭正好爱不彻，草木向荣情奈何。","便把樽罍通意思，须防风雨害清和。","千红万翠中间里，似我闲人更有么。"]},{"t":"年老逢春十三首 其五","f":"七言律诗","c":["年老逢春始识春，春妍都恐属闲身。","能知青帝功夫大，肯逐后生撩乱频。","酒趁嫩醅尝格韵，花承晓露看精神。","大凡尤物难分付，造化从来不负人。"]},{"t":"年老逢春十三首 其四","f":"七言律诗","c":["年老逢春莫厌春，住家况复在天津。","既将水竹为生计，须与风花作主人。","故宅废功除瓦砾，新畦加意种兰薰。","未知去此闲田地，何地更能容此身。"]},{"t":"年老逢春十三首 其三","f":"七言律诗","c":["年老逢春雨乍晴，雨晴况复近清明。","天低宫殿初长日，风暖园林未啭莺。","花似锦时高阁望，草如茵处小车行。","东君见赐何多也，又复人间久太平。"]},{"t":"年老逢春十三首 其二","f":"七言律诗","c":["年老逢春春正妍，春妍况在禁烟前。","才寒却暖养花日，行雨便晴消酒天。","进退樽罍宜有主，栽培桃李岂无权。","清谈已是欢情极，更把狂诗当管弦。"]},{"t":"年老逢春十三首 其一","f":"七言律诗","c":["年老逢春春莫猜，老年方自少年回。","人情少悦酒不解，天气却寒花未开。","堤外有风斜送柳，墙阴经雨半生苔。","去年波水东流去，旧渌奈何新又来。"]},{"t":"有客吟","f":"七言律诗","c":["伊嵩有客欲无言，进退由来尽俟天。","好静未能忘水石，乐闲非为学神仙。","休嗟紫陌难为客，且喜清风不用钱。","枉尺直寻何必较，此心都大不求全。"]},{"t":"老去吟 其二","f":"七言律诗","c":["行年六十有三岁，二十五年居洛阳。","林静城中得山景，池平坐上见江乡。","赏花长被杯盘苦，爱月屡为风露伤。","看了太平无限好，此身老去又何妨。"]},{"t":"老去吟","f":"七言律诗","c":["老去无成鬓已斑，纵心年纪合清闲。","如何得意云山外，更欲游心诗酒间。","大字写诗酬素志，小杯斟酒发酡颜。","春雷惊起千年蛰，笔下苍龙自往还。"]},{"t":"自乐吟","f":"七言律诗","c":["麟凤何尝不在郊，太平消得苦譊譊。","才闻善事心先喜，每见奇书手自抄。","一瓦清泉来竹下，两竿红日上松梢。","窝中睡起窝前坐，安得闲辞解客嘲。"]},{"t":"自处吟","f":"七言律诗","c":["尧夫自处道如何，满洛阳城都似家。","不德于人焉敢异，至诚从物更无他。","眼前只见罗天爵，头上谁知换岁华。","何止春归与春在，胸中长有四时花。"]},{"t":"自和打乖吟","f":"七言律诗","c":["安乐窝中好打乖，自知元没出人才。","老年多病不服药，少日壮心都已灰。","庭草刬除终未尽，槛花抬举尚难开。","轻风吹动半醺酒，此乐直从天外来。"]},{"t":"自咏","f":"五言律诗","c":["天下更无双，无知无所长。","年颜李文爽，风度贺知章。","静坐多茶饮，闲行或道装。","傍人休用笑，安乐是吾乡。"]},{"t":"自述二首 其二","f":"七言律诗","c":["陆海卧龙收爪甲，辽天老鹤戢毛衣。","难攀骐骥日千里，易足鹪鹩巢一枝。","最好朋侪同放适，博高台榭与登跻。","云山胜处追寻遍，似我清闲更有谁。"]},{"t":"自述二首 其一","f":"七言律诗","c":["何者堪名席上珍，都缘当日得师真。","是知佚我无如老，惟喜放怀长似春。","得志当为天下事，退居聊作水云身。","胸中一点分明处，不负高天不负人。"]},{"t":"自遣","f":"五言律诗","c":["读书忘岁月，人竞笑蹉跎。","但得甘旨足，宁辞辛苦多。","龙泉去铓刃，蜗角亦风波。","知我为亲老，不知将谓何。"]},{"t":"至福昌县作","f":"五言律诗","c":["清景几人爱，爱之当远寻。","及临韩岳近，始见洛川深。","县在云山腹，民居水竹心。","无机类闲物，愈觉少知音。"]},{"t":"观三国吟","f":"七言律诗","c":["桓桓鼎峙震雷音，绝唱高踪没处寻。","箫鼓一方情未畅，弓刀万里力难任。","论兵狼石宁无意，饮马黄河徒有心。","虽曰天时亦人事，谁知虑外失良金。"]},{"t":"观书吟","f":"七言律诗","c":["吁嗟四代帝王权，尽入区区一旧编。","或让或争三万里，相因相革二千年。","唐虞事业谁能继，汤武功夫世莫传。","时既不同人又异，仲尼恶得不潸然。"]},{"t":"观五代吟","f":"七言律诗","c":["自从唐季坠皇纲，天下生灵被扰攘。","社稷安危悬卒伍，朝廷轻重系藩方。","深冬寒木固不脱，未旦小星犹有光。","五十三年更五姓，始知除扫待真王。"]},{"t":"观西晋吟","f":"七言律诗","c":["承平未必便无忧，安若忘危非善谋。","题品人材凭雅诮，雌黄时事用风流。","有刀难剖公闾腹，无木可枭元海头。","祸在夕阳亭一句，上东门啸浪悠悠。"]},{"t":"观有唐吟","f":"七言律诗","c":["天生神武奠中央，不尔群凶未易攘。","贞观若无风凛凛，开元安有气扬扬。","凭高始见山河壮，入夏方知日月长。","三百年间能浑一，事虽成往道弥光。"]},{"t":"观两汉吟","f":"七言律诗","c":["秦破河山旧战场，岂期民复见耕桑。","九千来里开封域，四百馀年号帝王。","剥丧既而遭莽卓，经营殊不念高光。","当时文物如斯盛，城复何由更在隍。"]},{"t":"观盛化吟 其二","f":"七言律诗","c":["吾曹养拙赖明时，为幸居多宁不知。","天下英才中遁迹，人间好景处开眉。","生来只惯见丰稔，老去未尝经乱离。","五事历将前代举，帝尧而下固无之。"]},{"t":"观盛化吟 其一","f":"七言律诗","c":["纷纷五代乱离间，一旦云开复见天。","草木百年新雨露，车书万里旧山川。","寻常巷陌犹簪绂，取次园亭亦管弦。","人老太平春未老，莺花无害日高眠。"]},{"t":"观隋朝吟","f":"七言律诗","c":["始谋当日已非臧，又更相承或自戕。","蝼蚁人民贪土地，泥沙金帛悦姬姜。","征辽意思縻荒服，泛汴情怀厌未央。","三十六年都扫地，不然天下未归唐。"]},{"t":"观棋小吟","f":"七言律诗","c":["谁言博弈尚优游，利害相磨未始休。","初得手时宜顾望，合行权处莫迟留。","二年乃正三监罪，七日能尸两观囚。","天下太平无一事，南阳高卧更何求。"]},{"t":"观嬴秦吟","f":"七言律诗","c":["轰轰七国正争筹，利害相磨未便休。","比至一雄心底定，其如四海血横流。","三千宾客方成梦，百二山河又变秋。","谩说罢侯能置守，赵高元不是封侯。"]},{"t":"过比干墓","f":"五言律诗","c":["精诚皎于日，发出为忠辞。","方寸已尽破，独夫犹不知。","高坟临大道，老木无柔枝。","千古存遗像，翻为谄子嗤。"]},{"t":"过永济桥二首 其二","f":"五言律诗","c":["一水一溪门，溪门云复屯。","珍禽啭乔木，幽鹿走荒榛。","雨脚拖平地，稻畦扶远村。","高城半颓缺，兴废事休论。"]},{"t":"过永济桥二首 其一","f":"五言律诗","c":["山背锦屏开，河临永济回。","土田平似掌，桑柘大如槐。","斜日射虹去，低云将雨来。","无涯负清景，长是愧非才。"]},{"t":"过陕","f":"五言律诗","c":["吾祖道何光，二南分一方。","开周为太保，封陕辅成王。","岁月装辽邈，山川造渺茫。","世孙虽不肖，犹解忆甘棠。"]},{"t":"过潼关","f":"五言律诗","c":["禁密因离乱，机闲为太平。","山河虽设险，道德岂容争。","不究千一义，空传百二名。","遐方久无外，何复用鸡鸣。"]},{"t":"问人丐酒","f":"七言律诗","c":["百病筋骸一老身，白头今日愧因循。","虽无紫诏还朝速，却有青山入梦频。","风月满天谁是主，林泉遍地岂无人。","市沽酒味难醇美，长负襟怀一片春。"]},{"t":"问春吟","f":"七言律诗","c":["自古言花须说莺，莺花本合一时行。","因何花谢莺才至，浪得莺花相与名。","辄欲问春春不应，私于蜂蝶有何情。","流莺不伏春辜负，啼了千声又万声。"]},{"t":"何处是仙乡","f":"五言律诗","c":["何处是仙乡，仙乡不离房。","眼前无冗长，心下有清凉。","静处乾坤大，闲中日月长。","若能安得分，都胜别思量。"]},{"t":"初夏闲吟","f":"七言律诗","c":["绿杨深处啭流莺，莺语犹能喜太平。","人享永年非不幸，天生珍物岂无情。","牡丹谢后紫樱熟，芍药开时斑笋生。","林下一般闲富贵，何尝更肯让公卿。"]},{"t":"别谢君实端明","f":"五言律诗","c":["曹王八斗才，今日为余催。","锦绣佳章里，芝兰秀句开。","烦痾熸躯体，溽暑烁楼台。","宜把君诗讽，清风当自来。"]},{"t":"即事吟","f":"五言律诗","c":["事到患来频，何由得任真。","就新须果敢，从善莫因循。","盗亦自有道，人而或不仁。","义缘无定体，安处是行身。"]},{"t":"县尉廨宇莲池","f":"五言律诗","c":["县尉小斋前，水清池有莲。","岂唯观菡萏，兼可听潺湲。","宛类江湖上，殊非尘土边。","古人用心处，料得不徒然。"]},{"t":"听琴","f":"五言律诗","c":["琴宜入夜听，别起一般清。","才觉哀猿绝，还闻离凤鸣。","青山无限好，白发不须惊。","会取坐忘意，方知太古情。"]},{"t":"寿安县晚望","f":"七言律诗","c":["休叹浮生荣与辱，且听终日水潺潺。","遥穿暝霭孤鸿去，横截野烟双鹭还。","佳树排青岩下圃，好峰环翠县前山。","报言名利差轻者，少辍光阴到此间。"]},{"t":"弄笔","f":"五言律诗","c":["行年五十二，老去复何忧。","事贵照至底，话难言到头。","上有明天子，下有贤诸侯。","饱食高眠外，自馀无所求。"]},{"t":"求信吟","f":"五言律诗","c":["始则求人信，有知有不知。","既而求自信，人或多知之。","今我不求信，何人更起疑。","无可无不可，安往不熙熙。"]},{"t":"穷冬吟","f":"五言律诗","c":["十二月将终，还惊岁律穷。","藏冰方北陆，解冻未东风。","草昧徒寻绿，花梢强觅红。","探春春不见，元只在胸中。"]},{"t":"苍苍吟","f":"五言律诗","c":["人人共戴天，我戴岂徒然。","须识天人理，方知造化权。","功名归酒盏，器业入诗篇。","料得闲中乐，无如我得全。"]},{"t":"诏三下答乡人不起之意","f":"七言律诗","c":["生平不作皱眉事，天下应无切齿人。","断送落花安用雨，装添旧物岂须春。","幸逢尧舜为真主，且放巢由作外臣。","六十病夫宜揣分，监司无用苦开陈。"]},{"t":"还圆益上人诗卷","f":"七言律诗","c":["瓶锡相从更一巾，一巾曾拂十州尘。","心通佛性久无碍，口道儒言殊不陈。","吴越江山前日事，伊嵩风月此时身。","闲行闲坐松阴下，应恃眼明长笑人。"]},{"t":"闲中吟 其一","f":"五言律诗","c":["闲中气味长，长处是仙乡。","富有林泉乐，清无市井忙。","烂游千圣奥，醉拥万花香。","莫作伤心事，伤心易断肠。"]},{"t":"闲中吟 其二","f":"五言律诗","c":["闲中气味真，真处是天民。","富有林泉乐，清无市井尘。","烂游千圣奥，醉拥万花春。","莫作伤心事，伤心愁杀人。"]},{"t":"闲行吟 其二","f":"七言律诗","c":["投吴走越觅青天，殊不知天在眼前。","开眼见时犹有病，举头寻处更无缘。","颜渊正在如愚日，孟子方当不动年。","安得功夫游宝肆，爱人珠贝重忧钱。"]},{"t":"闲吟四首 其四","f":"五言律诗","c":["欲有一瓢乐，曾无二顷田。","丹诚未贯日，白发已华颠。","云意寒尤淡，松心老益坚。","年来疏懒甚，时忆旧林泉。"]},{"t":"闲吟四首 其三","f":"五言律诗","c":["居洛八九载，投心唯二三。","相逢各白首，共坐多清谈。","人事已默定，世情曾久谙。","酒行勿相逼，徐得奉醺酣。"]},{"t":"闲吟四首 其二","f":"五言律诗","c":["予年四十七，已甫知命路。","岂意天不绝，生男始为父。","且免散琴书，敢望大门户。","万事尽如此，何用过忧惧。"]},{"t":"闲吟四首 其一","f":"五言律诗","c":["平生如仕宦，随分在风波。","所损无纪极，所得能几何。","既乖经世虑，尚可全天和。","樽中有酒时，且饮复且歌。"]},{"t":"闲坐吟","f":"五言律诗","c":["当年计过之，今日事难随。","天命不我祐，云山聊自怡。","无何缘淡薄，遂得造希夷。","却欲嗤真宰，劳劳应不知。"]},{"t":"闲步吟","f":"五言律诗","c":["何者谓知音，知音难漫寻。","既无师旷耳，安有伯牙琴。","虽逼桑榆景，宁忘松桂心。","独行月堤上，一步一高吟。"]},{"t":"闲适吟五首 其四","f":"七言律诗","c":["南窗睡起望春山，山中霏微烟霭间。","千里难逃两眼净，百年未见一人闲。","情如落絮无高下，心似游丝自往还。","又恐幽禽知此意，故来枝上语绵蛮。"]},{"t":"闲适吟五首 其二","f":"七言律诗","c":["六尺眼前安乐身，四时争忍负佳辰。","温凉气候二八月，道义宾朋三五人。","量力杯盘随草具，开怀语笑任天真。","劝君似此清闲事，虽老何须更厌频。"]},{"t":"闲适吟五首 其五","f":"七言律诗","c":["谁将造化属东风，一属东风事莫穷。","残腊也宜先作策，新正其那便要功。","柳梢借暖浑摇软，梅萼偷春半露红。","安得向时情意在，轻衫撩乱少年中。"]},{"t":"闲适吟五首 其一","f":"七言律诗","c":["为士幸而居盛世，住家况复在中都。","虚名浮利非我有，绿水青山何处无。","选胜直宜寻美景，命俦须是择吾徒。","乐闲本属闲人事，又与偷闲事更殊。"]},{"t":"饮酒吟","f":"七言律诗","c":["时时醇酒饮些些，颐养天和以代茶。","无雨将成大凶岁，负城非有好生涯。","身居畎亩须忧国，事委男儿尚恤家。","人问老来何长进，鉴中添得鬓边华。"]},{"t":"依韵和三王少卿同过弊庐","f":"五言律诗","c":["洛中诗有社，马上句如神。","白首交情重，黄花节物新。","见过心可荷，知愧道非淳。","寂寞西风里，身闲半古人。"]},{"t":"依韵和王不疑少卿见赠","f":"七言律诗","c":["不把忧愁累物华，光阴过眼疾如车。","以平为乐忝知分，待足求安恐未涯。","食罢有时寻蕙圃，睡馀无事访僧家。","天津风月胜他处，长是思君共煮茶。"]},{"t":"依韵和王不疑少卿招饮","f":"五言律诗","c":["经难忆浮丘，吾乡足胜游。","风前惊白发，雨后喜新秋。","仕宦情虽薄，登临兴未休。","人间浪忧事，都不到心头。"]},{"t":"依韵和王安之少卿见戏安之非是弃尧夫吟","f":"七言律诗","c":["安之殊不弃尧夫，亦恐傍人有厚诬。","开叔当初言得罪，希淳在后说无辜。","悄然情意都如旧，刬地杯盘又见呼。","始信岁寒心未替，安之殊不弃尧夫。"]},{"t":"依韵和王安之少卿秋约吟","f":"五言律诗","c":["升沉恶足论，事体到头均。","一片蓬蒿地，千年云水身。","收成时正好，寒暖气初匀。","自此过从乐，诸公莫厌频。"]},{"t":"依韵和王安之少卿谢富相公诗","f":"七言律诗","c":["宠辱见多恶足惊，出尘还喜自诚明。","闲中气象乾坤大，静处光阴宇宙清。","素业经纶无少愧，全功天地不虚生。","野人何幸逢昌运，一百馀年天下平。"]},{"t":"依韵和王安之判监少卿","f":"七言律诗","c":["人行一善已为优，何况夫君百行修。","曩日慈闱贪眷恋，多年官路不追求。","官才少列辜清德，职异上庠尊白头。","洛社逾时阻相见，许多欢意却还休。"]},{"t":"依韵和王安之少卿六老诗仍见率成七首 其七","f":"七言律诗","c":["林下狂歌不帖腔，帖腔安得谓之狂。","小车行处莺花闹，大笔落时神鬼忙。","门掩柴荆阛阓远，墙开瓮牖薜萝香。","一般天下难寻物，洛浦清风拂面凉。"]},{"t":"依韵和王安之少卿六老诗仍见率成七首 其四","f":"七言律诗","c":["六人相聚会时康，著甚来由不放狂。","遍地园林同已有，满天风月助诗忙。","文章高摘汉唐艳，骚雅浓薰李杜香。","水际竹边闲适处，更无尘事只清凉。"]},{"t":"依韵和王安之少卿六老诗仍见率成七首 其六","f":"七言律诗","c":["见率野人成七老，野人唯解野疏狂。","编排每日清吟苦，趁辨递年闲适忙。","夏末喜尝新酒味，春初爱嗅早梅香。","问君何故须如此，不奈心头一点凉。"]},{"t":"依韵和王安之少卿六老诗仍见率成七首 其二","f":"七言律诗","c":["六老相陪卿与郎，闲曹饶却不清狂。","过从无事易成乐，职局向人难道忙。","烟柳嫩垂低更绿，露桃红裛暖仍香。","乘春醉卧花阴下，恰到花阴别是凉。"]},{"t":"依韵和田大卿见赠","f":"五言律诗","c":["日日步家园，清风不著钱。","城中得野景，竹下弄飞泉。","自愿无嗟若，何妨养浩然。","却惭天下士，语道未忘筌。"]},{"t":"依韵和刘职方见赠","f":"七言律诗","c":["造物工夫意自深，从吾所乐是山林。","少因多病不干禄，老为无才难动心。","花月静时行水际，蕙风香处卧松阴。","闲窗一觉从容睡，愿当封侯与赐金。"]},{"t":"依韵和吴传正寺丞见寄","f":"七言律诗","c":["五十年来读旧书，世间应笑我迂疏。","因思偊女忘今古，遂悟轮人致疾徐。","道业未醇诚可病，生涯虽薄敢言虚。","时和受赐已多矣，安有胸中不晏如。"]},{"t":"依韵和寿安尹尉有寄","f":"七言律诗","c":["不向红尘浪着鞭，殊无才业合时贤。","本酬壮志都无效，欲住青山却有缘。","翠竹阴中开缥帙，白云堆里揖飞泉。","锦屏正与溪南对，他日从游子子传。"]},{"t":"依韵和张子坚太博","f":"七言律诗","c":["八载相逢恨未平，如何别酒又还倾。","虽惭坦率珠多类，却识清和玉有声。","处世当为天下士，赏花须是洛阳城。","也知今古真男子，造化功夫不易生。"]},{"t":"依韵和陈成伯著作长寿雪会","f":"七言律诗","c":["琼苑群花一夜新，瑶台十二玉为尘。","城中竹叶涌增价，坐上杨花盛学春。","时会梁园皆墨客，谁思姑射有神人。","馀粮岂止千仓望，盈尺仍宜莫厌频。"]},{"t":"依韵和陈成伯著作史馆园会上作","f":"七言律诗","c":["竹绕长松松绕亭，令人到此骨毛清。","梅梢带雪微微拆，水脉连冰湱湱鸣。","残腊岁华无奈感，半醺襟韵不胜情。","谁怜相国名空在，吾道如何必可行。"]},{"t":"依韵和镇戎倅龚章屯田","f":"七言律诗","c":["十五年前初见君，见君情意便如亲。","虽然林下无他事，不那心间思故人。","万物比之论至底，丹诚到了总输真。","过从洛社胜诸处，何日能来共卜邻。"]},{"t":"依韵寄成都李希淳屯田","f":"五言律诗","c":["思君君未还，君恋蜀中官。","白首虽知倦，清衷宜自宽。","花时难得会，蚕市易成欢。","莫叹归休晚，生涯苦未完。"]},{"t":"依韵答友人","f":"七言律诗","c":["百万貔貅动塞尘，朝廷委寄不轻人。","胡儿生事虽然浅，国士尽忠须是纯。","陇上悲歌应愤惋，林间酣饮但酸辛。","欲陈一句好言语，只恐相知未甚真。"]},{"t":"依韵答王安之少卿","f":"七言律诗","c":["叠巘如屏四面开，可堪虚使乱云堆。","已曾同赏花无限，须约共游山几回。","未老秋光诗拥笔，乍凉天气酒盈杯。","轻风早是得人喜，更向芰荷深处来。"]},{"t":"依韵谢登封刘李裴三君见约游山","f":"七言律诗","c":["诸公见约往嵩前，重走新诗各一篇。","摆落尘埃非敢后，访寻云水奈输先。","三阳宫近丛幽石，万岁峰高羃紫烟。","多少胜游俱未到，愿陪仙躅共攀缘。"]},{"t":"和人放怀","f":"七言律诗","c":["为人虽未有前知，富贵功名岂力为。","涤荡襟怀须是酒，优游情思莫如诗。","况当水竹云山地，忍负风花雪月期。","男子雄图存用舍，不开眉笑待何时。"]},{"t":"和人闻韩魏公出镇永兴过洛","f":"七言律诗","c":["佐命三朝为太宰，名垂千古号元功。","栽培桃李满天下，出入风涛半海中。","虎帐夜寒心益壮，凤池波暖位犹空。","君王鼎盛子仪在，万里河湟不足攻。"]},{"t":"和内乡李师甫长官见寄 其一","f":"五言律诗","c":["虽未似神仙，能逃暑与寒。","何尝无水竹，未始离林峦。","道不同新学，才难动要官。","时和岁丰后，亦自有馀欢。"]},{"t":"和内乡李师甫长官见寄 其二","f":"五言律诗","c":["岁丰时又康，为邑在南阳。","不废吏民事，得游云水乡。","春输桃李艳，风荐蕙兰香。","太守兼贤杰，且无奔走忙。"]},{"t":"和王不疑郎中见赠","f":"七言律诗","c":["二十年来住洛都，眼前人事任纷如。","形同草木何胜野，心类钟彝不啻虚。","已沐仁风深骨髓，更惊诗思剧琼琚。","庄周休道亏名实，自是无才悦众狙。"]},{"t":"和王中美大卿致政二首 其二","f":"七言律诗","c":["自古有才思奋飞，夫君何故独知时。","平生怀抱未少屈，盛世挂冠良得宜。","入格柳拖风细细，压春花笑日迟迟。","传呼震地门前过，更不令人问是谁。"]},{"t":"和王中美大卿致政二首 其一","f":"七言律诗","c":["等候人间七十年，便如平子赋归田。","知时所得诚多矣，养志其谁曰不然。","况有林泉情悦乐，却无官守事拘牵。","小车近日曾驰谒，正值夫君春昼眠。"]},{"t":"和王安之少卿雨后","f":"五言律诗","c":["焦劳九夏馀，一雨物皆苏。","蛙鼓不足听，蚊雷未易驱。","非唯仰岁给，抑亦了官输。","林下闲游客，何妨尽自愉。"]},{"t":"和王安之少卿秋游","f":"七言律诗","c":["春夏而来可作诗，虽然可作待何为。","屡空滥得同颜子，历物固难如惠施。","风月情怀无奈处，云山意思不胜时。","一歌一咏聊酬唱，敢拒安之与静之。"]},{"t":"和王安之少卿韵","f":"七言律诗","c":["却恐乡人未甚知，相知深后又何疑。","贫时与禄是可受，老后得官难更为。","自有林泉安素志，况无才业动丹墀。","荀杨若守吾儒分，免被韩文议小疵。"]},{"t":"和王规甫司勋见赠","f":"七言律诗","c":["何止千年与万年，岁寒松桂独依然。","若无扬子天人学，安有庄生内外篇。","已约月陂寻白石，更期金谷弄清泉。","谁云影论纷纭甚，一任山巅复起巅。"]},{"t":"和孙传师秘校见赠","f":"七言律诗","c":["天津南畔是吾庐，时荷夫君枉乘车。","始为退来忘检束，却因闲久长空疏。","与其功业逋青史，孰若云山负素书。","一片丹诚最难状，庶几长得类舟虚。"]},{"t":"和君实端明","f":"五言律诗","c":["养道自安恬，霜毛一任添。","且无官责咎，幸免世猜嫌。","蓬户能安分，藜羹固不厌。","一般偏好处，曝背向前檐。"]},{"t":"和君实端明见赠","f":"五言律诗","c":["曾不见譊譊，城中类远郊。","虽无千里马，却有一枝巢。","月出云山背，风来松竹梢。","顽然何所得，岂复避人嘲。"]},{"t":"和君实端明花庵独坐","f":"五言律诗","c":["静坐养天和，其来所得多。","耽耽同厦宇，密密引藤萝。","忘去贵臣度，能容野客过。","系时休戚重，终不道如何。"]},{"t":"和吴冲卿省副见赠","f":"七言律诗","c":["非有非无是祖乡，都来相去一毫芒。","人人可到我未到，物物不妨谁与妨。","失即肝脾为楚越，得之藜藿是膏粱。","一言千古难知处，妙用仍须看吕梁。"]},{"t":"和张二少卿丈白菊","f":"五言律诗","c":["清淡晓凝霜，宜乎殿颢商。","自知能洁白，谁念独芬芳。","岂为琼无艳，还惊雪有香。","素英浮玉液，一色混瑶觞。"]},{"t":"和李文思早秋五首 其五","f":"五言律诗","c":["日脚云微淡，林梢叶渐黄。","可堪须变色，彻了为侵霜。","酒到难成醉，风来易得凉。","老年何所欲，唯愿且平康。"]},{"t":"和李文思早秋五首 其四","f":"五言律诗","c":["池畔拖垂柳，栏边笑晚花。","败荷倾弊盖，老桧露枯槎。","岁暮惊时态，年高惜物华。","东陵风未替，解忆故园瓜。"]},{"t":"和李文思早秋五首 其三","f":"五言律诗","c":["王金秋已至，烁石景方阑。","直养能希孟，闲居肯让潘。","竹间风嘒嘒，松罅月团团。","洛社多贤友，人人可共欢。"]},{"t":"和李文思早秋五首 其二","f":"五言律诗","c":["径小新经雨，庭幽遍有苔。","风前闲意思，阶下静徘徊。","不分筋骸老，难甘岁月催。","时时藉芳草，赖有酒同杯。"]},{"t":"和李文思早秋五首 其一","f":"五言律诗","c":["一雨洗觚棱，三川气象清。","林风传颢气，木叶送商声。","忽忽莲生的，看看菊吐英。","太平时里老，何以报虚生。"]},{"t":"和李审言龙图大雪","f":"七言律诗","c":["万树琼花一夜开，都和天地色皑皑。","素娥腰细舞将彻，白玉堂深曲又催。","瓮牖书生方挟策，沙场甲士正衔枚。","幽人骨瘦欲清损，赖有时时酒一杯。"]},{"t":"和花庵上牵牛花","f":"五言律诗","c":["叶闹深如幄，花繁翠似钿。","瀼瀼零晓露，羃羃蔽晴烟。","谢既成番次，开仍有后先。","主人凝伫苦，长是废朝眠。"]},{"t":"和闲来","f":"五言律诗","c":["以身观万物，万物理非遥。","马为乘多瘦，龟因灼苦焦。","能言谢鹦鹉，易饱过鹪鹩。","伊洛好烟水，愿同渔与樵。"]},{"t":"和和承制见赠","f":"七言律诗","c":["自度无能处世间，经冬经夏掩柴关。","青云路稳无功上，翠竹丛疏有分闲。","犹许艳花酬素志，更将佳酒发酡颜。","年来老态非常甚，长惧英才未易攀。"]},{"t":"和相国元老","f":"五言律诗","c":["崇台未经庆，瑞雪下云端。","虽地尽成白，而天不甚寒。","有年丰可待，盈尺润难乾。","畎亩无忘处，追踪击壤欢。"]},{"t":"和祖龙图见寄","f":"七言律诗","c":["吾家职分是云山，不见云山不解颜。","游兴亦难拘日阻，梦魂都不到人间。","烟岚欲极无涯乐，轩冕何尝有暂闲。","洛社交朋屡相约，几时曾得略跻攀。"]},{"t":"和绛守王仲贤郎中","f":"七言律诗","c":["为郎得绛分铜虎，见寄诗中非浪誇。","地土尚传唐草木，山川犹起晋云霞。","园池富有吟供笔，风俗淳无讼到衙。","太守下车民受赐，一心殊不负官家。"]},{"t":"和赵充道秘丞见赠","f":"七言律诗","c":["人言人事危冠冕，吾爱吾庐远市朝。","野面不堪趋魏阙，闲身唯称访杨寥。","殊无纪律诗千首，富有云山酒一瓢。","预借轩车又东去，自兹风月恐难招。"]},{"t":"和商守西楼雪霁","f":"七言律诗","c":["大雪初晴日半曛，高楼何惜上仍频。","数峰崷崒剑铓立，一水萦纡冰缕新。","昆岭移归都是玉，天河落后尽成银。","幽人自恨无佳句，景物从来不负人。"]},{"t":"和商守雪残登楼","f":"七言律诗","c":["残雪已消冰已开，风光渐觉拥楼台。","旅人未遂日边去，春色又从天上来。","况是樽中常有酒，岂堪岭上却无梅。","若非太守金兰契，谁肯倾心重不才。"]},{"t":"和商守雪霁对月","f":"七言律诗","c":["雪满群山霜满庭，光寒月碾一轮轻。","羁怀殊少向时乐，皓彩空多此夜明。","竹近帘栊饶碎影，风涵台榭有馀清。","恨无好句酬佳景，徒自凄凉梦不成。"]},{"t":"和商守雪霁登楼","f":"七言律诗","c":["百尺危楼小雪晴，晚来闲望逼人清。","山横暮霭高还下，水隔疏林淡复明。","天际落霞千万缕，风馀残角两三声。","此时此景真堪画，只恐丹青笔未精。"]},{"t":"和商守登楼看雪","f":"七言律诗","c":["西楼赏雪眼偏明，次第身疑在水晶。","千片万片巧妆地，半舞半飞斜犯楹。","形如玉屑依还碎，体似杨花又更轻。","谁谓天涯有羁客，一般对酒两般情。"]},{"t":"和商守新岁","f":"七言律诗","c":["衰躯在旅逢新岁，因感平生鬓易凋。","饮罢襟怀还寂寞，欢馀情绪却无聊。","望仙风月晴偏好，抹绿帘栊夜正遥。","对此块然唯土木，降兹未始不魂销。"]},{"t":"和登封裴寺丞翰见寄","f":"七言律诗","c":["陋巷箪瓢世所传，予何人则耻萧然。","既知富贵须由命，难把升沉更问天。","静默有功成野性，骞骧无路学时贤。","纷华出入金门者，应笑溪翁治石田。"]},{"t":"和魏教授见赠","f":"七言律诗","c":["清世文章日月悬，无才唯幸乐丰年。","游山太室更少室，看水伊川又洛川。","古有孟轲难语觉，时无颜子易为贤。","读书每到天根处，长惧诸公问极玄。"]},{"t":"和夔峡张宪白帝城怀古","f":"七言律诗","c":["不愤曹公跨许昌，苟非梁益莫争王。","三分区宇风雷恶，横截西南气势强。","行客往来闲指点，史官褒贬浪文章。","后人未识兴亡意，请看江心旧战场。"]},{"t":"所感吟","f":"五言律诗","c":["人生无定准，事体有多端。","客宦危疑处，家书子细看。","既曾忧险阻，方信喜平安。","男子平生事，须于痛定观。"]},{"t":"放小鱼","f":"五言律诗","c":["纤鳞不足留，此失一生休。","放尔江湖去，宽渠鼎镬游。","更宜深避网，慎勿误吞钩。","天下多庖者，无令落庶羞。"]},{"t":"放言","f":"五言律诗","c":["既得希夷乐，曾无宠辱惊。","泥空终是着，齐物到头争。","忽忽闲拈笔，时时自写名。","谁能苦真性，情外更生情。"]},{"t":"林下五吟 其二","f":"七言律诗","c":["老年躯体索温存，安乐窝中别有春。","万事去心闲偃仰，四支由我任舒伸。","庭花盛处凉铺簟，檐雪飞时软布裀。","谁道山翁拙于用，也能康济自家身。"]},{"t":"林下五吟 其四","f":"七言律诗","c":["相招相劝饮流霞，鬓乱秋霜发乱华。","所记莫非前甲子，凡经多是老官家。","共誇今日重孙过，更说当时旧事呀。","言语丁宁有情味，后生无笑太周遮。"]},{"t":"林下五吟 其五","f":"七言律诗","c":["生来未始事田畴，无岁无时长有秋。","随分杯盘俱是乐，等闲池馆便成游。","风花雪月千金子，水竹云山万户侯。","欲俟河清人寿几，两眉能著几多愁。"]},{"t":"林下五吟 其三","f":"七言律诗","c":["有物轻醇号太和，半醺中最得春多。","灵丹换骨还如否，白日升天似得么。","尽快意时仍起舞，到忘言处只讴歌。","宾朋莫怪无拘检，真乐攻心不奈何。"]},{"t":"牧童","f":"五言律诗","c":["随行笠与蓑，未始散天和。","暖戏荒城侧，寒偎古冢阿。","数声牛背笛，一曲陇头歌。","应是无心问，朝廷事若何。"]},{"t":"瓮牖吟","f":"五言律诗","c":["瓮破已甘弃，言收用有方。","用时须藉口，照处便安床。","不假轩窗力，能回日月光。","清平卧其下，自可比羲皇。"]},{"t":"知音吟","f":"七言律诗","c":["仲尼始可言无意，孟子方能不动心。","莫向山中寻白玉，但于身上觅黄金。","山中白玉有时得，身上黄金无处寻。","我辈何人敢称会，安知世上无知音。"]},{"t":"试砚","f":"七言律诗","c":["富贵傲人人未信，还知富贵去如何。","常观静处光阴好，亦恐闲时思虑多。","日出自然天不暗，风来安得水无波。","世间大有平田地，因甚须由捷径过。"]},{"t":"试笔","f":"七言律诗","c":["心在人躯号太阳，能于事上发辉光。","如何皎日照八表，得似灵台高一方。","家用平康贫不害，身无疾病瘦何妨。","高吟大笑洛城里，看尽人间手脚忙。"]},{"t":"金帛吟","f":"五言律诗","c":["金帛一种物，所用固不常。","聘则谓之币，赆则谓之将。","贸则谓之货，积则谓之藏。","赂则谓之贿，窃则谓之赃。"]},{"t":"南园花竹","f":"七言律诗","c":["花行竹径紧相挨，每日须行四五回。","因把花行侵竹种，且图竹径对花开。","花香远远随衣袂，竹影重重上酒杯。","谁道山翁少温润，这般红翠却长偎。"]},{"t":"一室吟","f":"五言律诗","c":["一室可容身，四时长有春。","何尝无美酒，未始绝佳宾。","洞里赏花者，天边泛月人。","相逢应有语，笑我太因循。"]},{"t":"恨月吟","f":"七言律诗","c":["我侬非是惜黄金，自是常娥爱负心。","初未上时犹露滴，恰才圆处便天阴。","栏干倚了还重倚，芳酒斟回又再斟。","安得深闺与收管，奈何前后误人深。"]},{"t":"春天吟","f":"七言律诗","c":["一片春天在眼前，眼前须识好春天。","春秋冬夏能无累，雪月风花都一连。","能用真腴为事业，岂防他物害暄妍。","我生其幸何多也，安有闲愁到耳边。"]},{"t":"春水短吟","f":"七言律诗","c":["雪消冰泮渌盈沟，翡翠鸳鸯得志秋。","长恨远山遮不断，又疑别浦去难留。","绕堤杨柳轻轻拂，近岸新蒲细细抽。","满眼烟波杳无际，三吴特地送孤舟。"]},{"t":"春尽后园闲步","f":"五言律诗","c":["绿树成阴日，黄莺对语时。","小渠初潋滟，新竹正参差。","倚杖闲吟久，携童引步迟。","好风知我意，故故向人吹。"]},{"t":"春阴 其一","f":"五言律诗","c":["日日是春阴，春阴又复沈。","养花虽有力，爱月岂无心。","月满方能看，花开始可吟。","奈何花与月，殊不谅人深。"]},{"t":"春日园中吟","f":"七言律诗","c":["春暖游园乃是常，城中殊不异仙乡。","竹间日日同真侣，水畔时时泛羽觞。","雨后鸟声移树啭，风前花气触人香。","林间富贵一般乐，更纵其来更不妨。"]},{"t":"春游五首 其五","f":"七言律诗","c":["三月牡丹方盛开，鼓声多处是亭台。","车中游女自笑语，楼下看人闲往来。","积翠波光摇帐幄，上阳花气扑樽罍。","西都风气所宜者，草木空妖谁复哀。"]},{"t":"春游五首 其四","f":"七言律诗","c":["人间佳节唯寒食，天下名园重洛阳。","金谷暖横宫殿碧，铜驼晴合绮罗光。","桥边杨柳细垂地，花外鞦韆半出墙。","白马蹄轻草如剪，烂游于此十年强。"]},{"t":"春游五首 其三","f":"七言律诗","c":["二月方当烂漫时，翠华未幸春无依。","绿杨阴里寻芳遍，红杏香中带醉归。","数片落花蝴蝶趁，一竿斜日流莺啼。","清樽有酒慈亲乐，犹得阶前戏綵衣。"]},{"t":"春游五首 其二","f":"七言律诗","c":["洛城春色浩无涯，春色城东又复嘉。","风力缓摇千树柳，水光轻荡半川花。","烟晴翡翠飞平岸，日暖鸳鸯下浅沙。","不见君王西幸久，游人但感鬓空华。"]},{"t":"春游五首 其一","f":"七言律诗","c":["五岭梅花迎腊开，三川正月赏寒梅。","相去万里先一月，始知春色从南来。","何人妙曲传羌笛，尽日清香落酒杯。","料得天涯未归客，也应临此重徘徊。"]},{"t":"昼梦","f":"五言律诗","c":["梦里到乡关，乡关二十年。","依稀新国土，隐约旧山川。","身已烟霞外，人家道路边。","觉来犹在目，一饷但萧然。"]},{"t":"洗竹","f":"七言律诗","c":["岁寒松柏共经秋，丛剉无端蔽翳稠。","遍地冗枝都与去，倚天高干一齐留。","应龙吟后声能效，仪凤来时功可收。","未说其他为用处，此般风格最难俦。"]},{"t":"洛下园池","f":"七言律诗","c":["洛下园池不闭门，洞天休用别寻春。","纵游只却输闲客，遍入何尝问主人。","更小亭栏花自好，尽荒台榭景才真。","虚名误了无涯事，未必虚名总到身。"]},{"t":"独坐吟 其二","f":"五言律诗","c":["天意自分明，人多不肯行。","莺花春乍暖，风月雨初晴。","静坐澄思虑，闲吟乐性情。","谁能事闲气，浪与世人争。"]},{"t":"盆池","f":"五言律诗","c":["三五小圆荷，盆容水不多。","虽非大薮泽，亦有小风波。","粗起江湖趣，殊无鸳鹭过。","幽人兴难遏，时绕醉吟哦。"]},{"t":"秋日","f":"七言律诗","c":["满目平原百里赊，寂寥深处见人家。","三间草屋无樵爨，一□□□有野花。","远出小童寻路径，归来老叟带烟霞。","数声起笛寒山暮，光照柴门月满斜。"]},{"t":"秋日饮后晚归","f":"七言律诗","c":["水竹园林秋更好，忍把芳樽容易倒。","重阳已过菊方开，情多不学年光老。","阴云不动杨柳低，风递轻寒生暮草。","无涯逸兴不可收，马蹄慢踏天街道。"]},{"t":"秋日饮郑州宋园示管城簿周正叔","f":"七言律诗","c":["二都相去四百里，中有名园属宋家。","古木参天罗剑戟，长藤垂地走龙蛇。","我来游日逢秋杪，君为开筵对晚花。","饮散竹轩微雨后，凌晨归路起栖鸦。"]},{"t":"秋日登崇德阁二首 其二","f":"七言律诗","c":["一百年来号太平，当初仍患不丁宁。","京都尚有汉唐气，宫阙犹虚霸王形。","烟外乱峰才隐约，霜馀红树半凋零。","樽中有酒难成醉，旋被西风吹又醒。"]},{"t":"秋日登崇德阁二首 其一","f":"七言律诗","c":["无限高贤抑壮图，登临不用起长吁。","山川千古战争后，冠剑百年零落馀。","浪把功名为己任，那知富贵岂人谟。","丹青曲尽世间妙，写得凭栏意思无。"]},{"t":"秋尽吟","f":"七言律诗","c":["数日之间秋遂尽，百思无以慰蹉跎。","园林正好爱不彻，草木已黄情奈何。","虽老筋骸行尚健，尽高台榭望仍多。","终朝把酒未成醉，又欲临风一浩歌。"]},{"t":"秋阁吟","f":"五言律诗","c":["秋阁一凭栏，人心何悄然。","乾坤今岁月，唐汉旧山川。","淡泊霜前日，萧疏雨后天。","丹青空妙手，此意有谁传。"]},{"t":"秋暮西轩","f":"七言律诗","c":["绕栏种菊一齐芳，户牖轩窗总是香。","得意不能无兴咏，乐时况复遇丰穰。","深秋景物随宜好，向老筋骸粗且康。","饮罢何妨更登眺，烂霞堆里有斜阳。"]},{"t":"秋游六首 其六","f":"七言律诗","c":["霜天寥落思无穷，不奈楼高逼望中。","四面溪山徒满目，九秋宫殿自危空。","云横远峤千寻直，霞乱斜阳数缕红。","无限伤情言不到，共谁开口向西风。"]},{"t":"秋游六首 其五","f":"七言律诗","c":["九月风光虽已暮，中州景物未全衰。","眼观秋色千万里，手把黄花三两枝。","美酒易消闲岁月，青铜休照老容仪。","若言必使他人信，沥尽丹诚谁肯知。"]},{"t":"秋游六首 其四","f":"七言律诗","c":["家住南城水竹涯，乘秋行乐未尝亏。","轻寒气候我自爱，半醉光阴人莫知。","信马天街微雨后，凭栏僧阁晚晴时。","十年美景追寻遍，好向风前摘白髭。"]},{"t":"秋游六首 其三","f":"七言律诗","c":["八月光阴未甚凄，松亭竹树尤为宜。","况当昼夜初停处，正是炎凉得所时。","明月入怀如有意，好风迎面似相知。","闲人歌咏自怡悦，不管朝廷不采诗。"]},{"t":"秋游六首 其二","f":"七言律诗","c":["先秋颢气已潜生，洛邑方知节候平。","庭院乍凉人共喜，园林经雨气尤清。","回舟伊水风微溜，缓辔天津月正明。","自有皋夔分圣念，好将诗酒乐升平。"]},{"t":"秋游六首 其一","f":"七言律诗","c":["七月芙蕖正烂开，东南园近日徘徊。","有时风向池心过，无限香从水面来。","罨画溪深方误入，洞庭湖晚未成回。","坐来一霎萧萧雨，又送新凉到酒杯。"]},{"t":"贺人致政","f":"七言律诗","c":["人情大率喜为官，达士何尝有所牵。","解印本非嫌薄禄，挂冠殊不为高年。","因通物性兴衰理，遂悟天心用舍权。","宜放襟怀在清景，吾乡况有好林泉。"]},{"t":"送王伯初学士赴北京机宜","f":"七言律诗","c":["丈夫志气盖棺定，自有雄图系重轻。","去路不能无感旧，到官争忍便忘情。","闲时语话贵精密，先事经营在太平。","谁谓禦戎无上策，伐人谋处不须兵。"]},{"t":"重九日登石阁三首 其三","f":"五言律诗","c":["今岁重阳日，凭栏气候迟。","云烟虽已淡，林木未全衰。","天地开怀处，山川快眼时。","栏干空倚遍，此意有谁知。"]},{"t":"重阳日再到共城百源故居","f":"五言律诗","c":["故国逢佳节，登临但可悲。","山川一梦外，风月十年期。","白发飘新鬓，黄花绕旧篱。","乡人应笑我，昼锦是男儿。"]},{"t":"重阳前一日作","f":"七言律诗","c":["近来多病不堪言，长欲醺醺带醉眠。","新酒乍逢重九日，好花初接小春天。","自知命薄临头上，不愿事多来眼前。","唯有天津横落照，水声仍是旧潺湲。"]},{"t":"首尾吟 其九十七","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫用畜时。","史籍始终明治乱，经书表里见安危。","庖羲可作三才主，孔子当为万世师。","不止前言与往行，尧夫非是爱吟诗。"]},{"t":"首尾吟 其九十三","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫注思时。","事少全由心易足，病多休道药难医。","情当少日须思老，志在安时莫忘危。","天道分明人自昧，尧夫非是爱吟诗。"]},{"t":"首尾吟 其八十三","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫恨月时。","见说天长在甚处，照教人老待奚为。","婵娟东面才如鉴，屈曲西边却似眉。","由此遂多悲与喜，尧夫非是爱吟诗。"]},{"t":"首尾吟 其九十四","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫行已时。","政在我时心必尽，事关人处力难为。","人如负我我何预，我若辜人人有词。","就责莫如躬自厚，尧夫非是爱吟诗。"]},{"t":"首尾吟 其三","f":"七言律诗","c":["尧夫非是爱吟诗，安乐窝中得意时。","志快不须求事显，书成当自有人知。","林泉且作酬心物，风月聊充藉手资。","多少宽平好田地，尧夫非是爱吟诗。"]},{"t":"首尾吟 其九十九","f":"七言律诗","c":["尧夫非是爱吟诗，诗是春秋后语时。","七国纵横如破的，九州吞吐若枰棋。","君臣自作逋逃主，将相无非市井儿。","篆入草书犹不误，尧夫非是爱吟诗。"]},{"t":"首尾吟 其五十六","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫试手时。","善死自明非不死，有知谁道胜无知。","杨朱眼泪惟能泣，宋玉心胸只解悲。","为报西风漫相侮，尧夫非是爱吟诗。"]},{"t":"首尾吟 其八十八","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫忖度时。","先见固能无后悔，至诚方始有前知。","己之欲处人须欲，心可欺时天可欺。","只被世人难易地，尧夫非是爱吟诗。"]},{"t":"首尾吟 其二十一","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫试砚时。","玉未琢前犹索辩，金经煅后更何疑。","当时掉臂人皆笑，今日摇头谁不知。","天外凤凰飞处别，尧夫非是爱吟诗。"]},{"t":"首尾吟 其十一","f":"七言律诗","c":["尧夫非是爱吟诗，诗是天津再住时。","积翠莺花供秀润，上阳风月助新奇。","凤凰楼观云中看，道德园林枕上窥。","不负太平吟笑事，尧夫非是爱吟诗。"]},{"t":"首尾吟 其六十七","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫重惜时。","西晋浮誇时可叹，南梁崇尚事堪悲。","仲尼岂欲轻辞鲁，孟子何尝便去齐。","仪凤不来人老去，尧夫非是爱吟诗。"]},{"t":"首尾吟 其二十二","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫试笔时。","以至死生犹处了，自馀荣辱可知之。","适居堂上行堂上，或在水湄言水湄。","不止省心兼省力，尧夫非是爱吟诗。"]},{"t":"首尾吟 其一三三","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫有愧时。","空受半来天下拜，却无些子自家为。","心能尽处我自慰，力不周时人亦知。","只恨一般言未得，尧夫非是爱吟诗。"]},{"t":"首尾吟 其三十","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫对酒时。","处世虽无一分善，行身误有四方知。","大凡观物须生意，既若成章必见辞。","诗者志之所之也，尧夫非是爱吟诗。"]},{"t":"首尾吟 其一一四","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫可叹时。","只被人间多用诈，遂令天下尽生疑。","樽前揖让三杯酒，坐上交争一局棋。","小大不同而已矣，尧夫非是爱吟诗。"]},{"t":"首尾吟 其三十九","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫自在时。","何处不行芳草地，谁家不望小车儿。","花枝好处安详折，酒盏满时撋就持。","闲气虚名都忘了，尧夫非是爱吟诗。"]},{"t":"首尾吟 其三十五","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫乐事时。","慷慨丈夫无后悔，分明男子有前知。","在寻常时观执守，当仓卒处看施为。","善事没身而已矣，尧夫非是爱吟诗。"]},{"t":"首尾吟 其一一五","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫凭式时。","乱法奈何非独古，措刑安得见于兹。","当时既有少正卯，今日宁无孔仲尼。","时世不同人一也，尧夫非是爱吟诗。"]},{"t":"首尾吟 其七十五","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫赞易时。","八卦小成皆有主，三才大备略无遗。","阴阳消长既未已，动静吉凶那不知。","为见至神功效远，尧夫非是爱吟诗。"]},{"t":"首尾吟 其二十四","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫语道时。","天听虽高只些子，人情相去没多儿。","无声无臭尽休也，不忮不求还得之。","虽有丹青亦难状，尧夫非是爱吟诗。"]},{"t":"首尾吟 其十四","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫默识时。","初有意时如父子，到无情处类蛮夷。","眼前成败尚不见，天下安危那得知。","始信知人是难事，尧夫非是爱吟诗。"]},{"t":"首尾吟 其六","f":"七言律诗","c":["尧夫非是爱吟诗，为见兴衰各有时。","天地全功须发露，朝廷盛美在施为。","便都默默奈何见，若不云云那得知。","事在目前人不虑，尧夫非是爱吟诗。"]},{"t":"首尾吟 其六十三","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫代记时。","官职固难称太史，文章却欲学宣尼。","能归岂谢陶元亮，善听何惭钟子期。","德若不孤吾道在，尧夫非是爱吟诗。"]},{"t":"首尾吟 其四十一","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫自得时。","风露清时收翠润，山川秀处摘新奇。","揄扬物性多存体，拂掠人情薄用辞。","遗味正宜涵泳处，尧夫非是爱吟诗。"]},{"t":"首尾吟 其九十","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫恣纵时。","在世上官虽不做，出人间事却能知。","待天春暖秋凉日，是我东游西泛时。","道在眼前人不见，尧夫非是爱吟诗。"]},{"t":"首尾吟 其一二一","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫谈笑时。","国士待人能尽意，山翁道我会开眉。","盏随酒量徐徐饮，榻逐花阴旋旋移。","此乐再寻非易得，尧夫非是爱吟诗。"]},{"t":"首尾吟 其七","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫不寐时。","咀茹兰薰宜有主，恢张风雅更为谁。","三千来首收清月，二十馀年撚白髭。","了却许多闲职分，尧夫非是爱吟诗。"]},{"t":"首尾吟 其八十一","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫先见时。","直在胸中贫亦乐，屈于人下贵奚为。","谁何药可医无病，多少金能买不疑。","迟老更逢春不老，尧夫非是爱吟诗。"]},{"t":"首尾吟 其一一○","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫掩卷时。","时过犹能用归妹，物伤长惧入明夷。","夏商盛日何由见，唐汉衰年争忍思。","畎亩不忘天下处，尧夫非是爱吟诗。"]},{"t":"首尾吟 其一二九","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫喜老时。","明著衣冠为士子，高谈仁义作男儿。","敢于世上明开眼，肯向人间浪皱眉。","六十七年无事客，尧夫非是爱吟诗。"]},{"t":"首尾吟 其五十八","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫相度时。","合放手时须放手，得开眉处且开眉。","狂情多见好人喜，僻性少为他物移。","只恨一般言不到，尧夫非是爱吟诗。"]},{"t":"首尾吟 其四十七","f":"词","c":["尧夫非是爱吟诗，诗是尧夫自喜时。","不用虚名矜智数，且无闲气挠心脾。","酒佳蓦地泛一?，花好有时簪两枝。","更纵无人讶狂怪，尧夫非是爱吟诗。"]},{"t":"首尾吟 其十六","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫自励时。","适道全由就师学，出尘须是禀天资。","好贤只恐知人晚，乐善惟忧见事迟。","多谢友朋常见教，尧夫非是爱吟诗。"]},{"t":"首尾吟 其五十九","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫乐物时。","天地精英都已得，鬼神情状又能知。","陶真意向辞中见，借论言从意外移。","始信诗能通造化，尧夫非是爱吟诗。"]},{"t":"首尾吟 其五十四","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫髣髴时。","写字吟诗为润色，通经达道是镃基。","经纶亦可为馀事，性命方能尽所为。","可谓一生男子事，尧夫非是爱吟诗。"]},{"t":"首尾吟 其一二八","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫得意时。","这意著何言语道，此情惟用喜欢追。","仙家气象闲中见，真宰功夫静处知。","不必深山更深处，尧夫非是爱吟诗。"]},{"t":"首尾吟 其一三二","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫有激时。","留在胸中防作恨，发于词上恐成疵。","芝兰见处须收采，金玉逢时莫弃遗。","到此尧夫常自贺，尧夫非是爱吟诗。"]},{"t":"首尾吟 其八十五","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫中夜时。","拥被不眠还展转，披衣却坐忽寻思。","死生有命尚能处，道德由人却不知。","须是安之以无事，尧夫非是爱吟诗。"]},{"t":"首尾吟 其一○五","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫自诧时。","许大天时犹可测，些儿人事岂难知。","昆岗美玉人谁识，沧海明珠世莫窥。","由是尧夫聊自诧，尧夫非是爱吟诗。"]},{"t":"首尾吟 其四十二","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫默坐时。","天意教闲须有谓，人心刚动似无知。","烟轻柳叶眉闲皱，露重花枝泪静垂。","应恨尧夫无一语，尧夫非是爱吟诗。"]},{"t":"首尾吟 其一○二","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫处否时。","信道而行安有悔，乐天之外更何疑。","受疑始见周公旦，经阨方明孔仲尼。","大圣大神犹不免，尧夫非是爱吟诗。"]},{"t":"首尾吟 其七十九","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫不著棋。","大智大谋难忘设，小机小数肯轻为。","泥沙用处宁无惜，蝼蚁驱时忍更窥。","天下也宜留一路，尧夫非是爱吟诗。"]},{"t":"首尾吟 其一二二","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫惊骇时。","暮雨朝云才半日，春华秋叶未多时。","即今世态已堪叹，过此人情更可知。","一暑一寒何太急，尧夫非是爱吟诗。"]},{"t":"首尾吟 其一一二","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫默识时。","日月既来还却往，园林才盛又成衰。","登山高下虽然见，临水浅深那不知。","世上高深事无限，尧夫非是爱吟诗。"]},{"t":"首尾吟 其一○七","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫慎与时。","初作事时分可否，始亲人处定安危。","殊乡忠信同思善，异世奸邪共喜私。","岂待较量然后见，尧夫非是爱吟诗。"]},{"t":"首尾吟 其二","f":"七言律诗","c":["尧夫非是爱吟诗，安乐窝中坐看时。","一气旋回无少息，两仪覆焘未尝私。","四时更革互为主，百物新陈争效奇。","享了许多家乐事，尧夫非是爱吟诗。"]},{"t":"首尾吟 其九十六","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫尽性时。","若圣与仁虽不敢，乐天知命又何疑。","恢恢志意方闲暇，绰绰情怀正坦夷。","心逸日休难状处，尧夫非是爱吟诗。"]},{"t":"首尾吟 其一一六","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫自信时。","必欲全然无后悔，直须晓了有前知。","言忠能尽己所有，事善任他人致疑。","外物从来自难必，尧夫非是爱吟诗。"]},{"t":"首尾吟 其十八","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫可叹时。","固有命焉刚不信，是无天也果能欺。","才高正被聪明使，身贵方为利害移。","无计奈何春又老，尧夫非是爱吟诗。"]},{"t":"首尾吟 其八十七","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫信脚时。","高祖宅前花似锦，魏王堤畔柳如丝。","因闲看水行来远，就便游园归去迟。","每遇好风还眷眷，尧夫非是爱吟诗。"]},{"t":"首尾吟 其九十五","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫自省时。","义若不为无勇也，幸如有过必知之。","面前地恶犹能扫，心上田荒何所欺。","从谏如流是难事，尧夫非是爱吟诗。"]},{"t":"首尾吟 其五十三","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫重惜时。","万里焦劳无所诉，九重深邃莫能知。","二年斯得诚为晚，七日言诛未是迟。","本固邦宁王道在，尧夫非是爱吟诗。"]},{"t":"首尾吟 其一三四","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫赞易时。","士昧固难分体用，人灵岂不异蓍龟。","吉凶只向面前决，动静何烦心上疑。","由此敢开天下口，尧夫非是爱吟诗。"]},{"t":"首尾吟 其七十八","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫可爱时。","已著意时仍著意，未加辞处与加辞。","物皆有理我何者，天且不言人代之。","代了天工无限说，尧夫非是爱吟诗。"]},{"t":"首尾吟 其二十八","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫隐几时。","尺寸光阴须爱惜，分毫头角莫矜驰。","酒因劝客小盏饮，句到惊人大笔麾。","无入何尝不自得，尧夫非是爱吟诗。"]},{"t":"首尾吟 其三十六","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫自喜时。","名在士人当盛世，生于中国作男儿。","良辰美景忍虚废，骤雨飘风无定期。","过此焉能事追悔，尧夫非是爱吟诗。"]},{"t":"首尾吟 其三十四","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫可叹时。","大器晚成当自重，小人难养又何疑。","既无一日九迁则，安有终朝三褫之。","若向槿花求远到，尧夫非是爱吟诗。"]},{"t":"首尾吟 其一○九","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫重惜时。","争向伪时须便信，奈何真处却生疑。","既称有客告曾子，岂为无人毁仲尼。","父子君臣独未免，尧夫非是爱吟诗。"]},{"t":"首尾吟 其九","f":"七言律诗","c":["尧夫非是爱吟诗，虽老精神未耗时。","水竹清闲先据了，莺花富贵又兼之。","梧桐月向怀中照，杨柳风来面上吹。","被有许多闲捧拥，尧夫非是爱吟诗。"]},{"t":"首尾吟 其六十","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫不乐时。","明月恰圆还却缺，好花才盛又成衰。","返魂丹向何人用，续命汤于甚处施。","天听虽高只些子，尧夫非是爱吟诗。"]},{"t":"首尾吟 其一一八","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫何所为。","睡思动时亲瓮牖，幽情发处旁盆池。","寻芳更用小车去，得句仍将大笔麾。","馀事不妨闲润色，尧夫非是爱吟诗。"]},{"t":"首尾吟 其一一三","f":"七言律诗","c":["尧夫非是爱吟诗，诗是尧夫自试时。","事体待谙然后信，人情非久莫能知。","同沾雨露蒿莱质，独出雪霜松柏姿。","见惯不如身历过，尧夫非是爱吟诗。"]},{"t":"哭张师柔长官","f":"七言律诗","c":["生平志在立功名，谁谓才难与命争。","绝笔有诗形雅意，盖棺无地尽交情。","胸中时事何由展，天下人才不复评。","魂若有知宜自慰，子孙大可振家声。"]},{"t":"悟人一言","f":"五言律诗","c":["百虑谋犹拙，一言迷自开。","世间无大事，天下有雄才。","唯恐人难得，宁忧道未恢。","忌心都去尽，何复病尘埃。"]}]};